test("Settings › Rem model menus show the app's default as Automatic until a model is picked", () => {
  const { RemModelSelect } = settingsPopoverModule;
  const provider = {
    id: "claude_code",
    defaultModel: "m2",
    models: [{ id: "m1", displayName: "M1" }, { id: "m2", displayName: "M2" }],
  };
  const render = (value) => renderToStaticMarkup(React.createElement(RemModelSelect, { provider, value, onChange() {} }));

  const empty = render("");
  assert.match(empty, /<option value="" selected="">Automatic \(m2\)<\/option>/);
  assert.ok(empty.indexOf("Automatic (m2)") < empty.indexOf(">M1<"));
  assert.match(render("cli-default"), /<option value="" selected="">Automatic \(m2\)<\/option>/);
  const picked = render("m1");
  assert.match(picked, /<option value="m1" selected="">M1<\/option>/);
  assert.match(picked, /<option value="">Automatic \(m2\)<\/option>/);
  assert.match(render("gone"), /<option value="gone" selected="">gone \(unavailable\)<\/option>/);
  assert.match(renderToStaticMarkup(React.createElement(RemModelSelect, { provider: { models: [] }, value: "m1", onChange() {} })), /disabled=""[^>]*>.*<option value="m1" selected="">m1<\/option>/);
});

test("studio session persists the selected project, workflow, and editor", () => {
  const stored = new Map();
  const storage = {
    getItem: (key) => stored.get(key) ?? null,
    setItem: (key, value) => stored.set(key, value),
  };

  const saved = appModule.saveStudioSession({
    projectRoot: " /projects/gofer-flow ",
    view: "code",
    workflowId: "testing",
  }, storage);

  assert.deepEqual(saved, {
    projectRoot: "/projects/gofer-flow",
    view: "code",
    workflowId: "testing",
  });
  assert.deepEqual(appModule.loadStudioSession(storage), saved);

  stored.set(appModule.STUDIO_SESSION_STORAGE_KEY, JSON.stringify({
    projectRoot: 42,
    view: "invalid",
    workflowId: null,
  }));
  assert.deepEqual(appModule.loadStudioSession(storage), {
    projectRoot: "",
    view: "",
    workflowId: "",
  });
});

test("text zoom clamps stored values and recognizes keyboard zoom shortcuts", () => {
  const storage = {
    getItem: () => "175",
  };
  assert.equal(appSettingsModule.loadTextZoom(storage), 150);
  assert.equal(appSettingsModule.nextTextZoom(100, 1), 110);
  assert.equal(appSettingsModule.nextTextZoom(80, -1), 80);
  assert.equal(appSettingsModule.textZoomDirection({ ctrlKey: true, key: "+" }), 1);
  assert.equal(appSettingsModule.textZoomDirection({ ctrlKey: true, key: "-" }), -1);
  assert.equal(appSettingsModule.textZoomDirection({ ctrlKey: true, key: "a" }), 0);
});

test("text zoom stays consistent across views and ignores the graph visualization", async () => {
  const workflow = workflowFixture();
  const zoomFactors = [];
  let sendBrowserCommand;
  const fetchMock = createFetchMock([
    jsonResponse("/api/workflows", workflowsPayload([workflow])),
  ]);
  const dom = await mountReact(React.createElement(appModule.default), fetchMock, {
    browser: {
      onCommand(callback) {
        sendBrowserCommand = callback;
        return () => {};
      },
    },
    desktop: {
      appearance: {
        setZoomFactor(value) {
          zoomFactors.push(value);
        },
      },
      workspace: {
        async gitStatus() { return { active: false, entries: [] }; },
        async listDirectory() { return { directory: "/workspace", entries: [] }; },
        async trustProjectRoot() {},
      },
    },
    storage: {
      [appModule.STUDIO_SESSION_STORAGE_KEY]: JSON.stringify({
        projectRoot: "/workspace",
        view: "code",
        workflowId: workflow.id,
      }),
      [appSettingsModule.TEXT_ZOOM_STORAGE_KEY]: "100",
    },
  });

  await dom.flush();
  assert.equal(zoomFactors.at(-1), 1);
  assert.ok(dom.byLabel("App zoom 100%."));

  await dom.dispatchWindow("keydown", { ctrlKey: true, key: "+" });
  assert.equal(zoomFactors.at(-1), 1.1);
  assert.ok(dom.byLabel("App zoom 110%."));

  await dom.dispatchWindow("wheel", { ctrlKey: true, deltaY: 100 });
  assert.equal(zoomFactors.at(-1), 1);

  await React.act(async () => {
    sendBrowserCommand({ action: "text-zoom", direction: 1 });
  });
  assert.equal(zoomFactors.at(-1), 1.1);

  await React.act(async () => {
    sendBrowserCommand({ action: "text-zoom", direction: -1 });
  });
  assert.equal(zoomFactors.at(-1), 1);

  await React.act(async () => {
    sendBrowserCommand({ action: "text-zoom", reset: true });
  });
  assert.equal(zoomFactors.at(-1), 1);

  await dom.dispatchWindow("keydown", { ctrlKey: true, key: "+" });
  await dom.click(dom.byLabel("Workflows"));
  await dom.click(dom.ancestor(dom.byText(workflow.name), node => node.getAttribute?.("role") === "button"));
  assert.equal(zoomFactors.at(-1), 1.1);
  assert.ok(dom.byLabel("App zoom 110%."));

  const graphVisualization = dom.byLabel("Workflow graph visualization");
  const callCount = zoomFactors.length;
  await dom.dispatchWindow("keydown", {
    ctrlKey: true,
    key: "+",
    target: graphVisualization,
  });
  assert.equal(zoomFactors.length, callCount);

  await dom.dispatchWindow("wheel", {
    ctrlKey: true,
    deltaY: -100,
    target: graphVisualization,
  });
  assert.equal(zoomFactors.length, callCount);

  await dom.dispatchWindow("keydown", {
    ctrlKey: true,
    key: "-",
    target: dom.byTitle("Validate workflow"),
  });
  assert.equal(zoomFactors.at(-1), 1);

  await dom.click(dom.byLabel("File explorer"));
  assert.equal(zoomFactors.at(-1), 1);
  await dom.unmount();
  assert.equal(zoomFactors.at(-1), 1);
});

test("device settings select and test a microphone with a live input meter", async () => {
  let requestedConstraints;
  let stopped = false;
  class FakeAudioContext {
    async resume() {}
    async close() {}
    createMediaStreamSource() {
      return { connect() {}, disconnect() {} };
    }
    createAnalyser() {
      return {
        fftSize: 0,
        getByteTimeDomainData(samples) {
          samples.fill(160);
        },
      };
    }
  }
  function SettingsHarness() {
    const [settings, setSettings] = React.useState(settingsModule.DEFAULT_APP_SETTINGS);
    return React.createElement(settingsPopoverModule.default, {
      onChange: (path, value) => setSettings((current) => (
        settingsModule.updateSetting(current, path, value)
      )),
      onClose() {},
      onResetAll() {},
      open: true,
      settings,
    });
  }

  const dom = await mountReact(React.createElement(SettingsHarness), createFetchMock([
    jsonResponse("/api/devices", { experimental_network: true, enabled: false, peers: [] }),
  ]));
  navigator.mediaDevices = {
    async enumerateDevices() {
      return [{ deviceId: "studio-mic", kind: "audioinput", label: "Studio microphone" }];
    },
    async getUserMedia(constraints) {
      requestedConstraints = constraints;
      return { getTracks: () => [{ stop() { stopped = true; } }] };
    },
  };
  window.AudioContext = FakeAudioContext;

  await dom.click(dom.byText("Devices"));
  await dom.flush();
  assert.ok(dom.byLabel("Paired devices"));
  assert.match(dom.text(), /Set up device pairing/);
  const deviceSelect = dom.byLabel("Microphone input device");
  await dom.change(deviceSelect, "studio-mic");
  await dom.click(dom.byLabel("Test microphone"));
  await dom.flush(100);

  assert.equal(requestedConstraints.audio.deviceId.exact, "studio-mic");
  assert.ok(Number(dom.byLabel("Microphone input level").getAttribute("aria-valuenow")) > 0);
  assert.match(dom.text(), /Input detected/);
  await dom.click(dom.byLabel("Stop microphone test"));
  assert.equal(stopped, true);

  delete window.AudioContext;
  await dom.unmount();

  // With pairing off in Feature Preview, Devices shows no pairing controls.
  const offDom = await mountReact(React.createElement(SettingsHarness), createFetchMock([
    jsonResponse("/api/devices", { experimental_network: false, enabled: true, peers: [] }),
  ]));
  try {
    await offDom.click(offDom.byText("Devices"));
    await offDom.flush();
    assert.equal(allElements(offDom.container).some(node => node.getAttribute?.("aria-label") === "Paired devices"), false);
    assert.doesNotMatch(offDom.text(), /Phone connections|device pairing|RATICODE_DEVICE/);
  } finally { await offDom.unmount(); }
});

test("testing a microphone that sends no sound says it may be muted, and clears once sound arrives", async () => {
  let exactSamples = 0;
  class SilentAudioContext {
    async resume() {}
    async close() {}
    createMediaStreamSource() { return { connect() {}, disconnect() {} }; }
    createAnalyser() {
      return {
        fftSize: 0,
        getByteTimeDomainData(samples) { samples.fill(exactSamples ? 160 : 128); },
        getFloatTimeDomainData(samples) { samples.fill(exactSamples); },
      };
    }
  }
  function SettingsHarness() {
    const [settings, setSettings] = React.useState(settingsModule.DEFAULT_APP_SETTINGS);
    return React.createElement(settingsPopoverModule.default, {
      onChange: (path, value) => setSettings((current) => settingsModule.updateSetting(current, path, value)),
      onClose() {}, onResetAll() {}, open: true, settings,
    });
  }
  const dom = await mountReact(React.createElement(SettingsHarness), createFetchMock([
    jsonResponse("/api/devices", { experimental_network: false, enabled: true, peers: [] }),
  ]));
  const track = { label: "C920 PRO HD Webcam Analog Stereo", stop() {} };
  navigator.mediaDevices = {
    async enumerateDevices() { return [{ deviceId: "webcam", kind: "audioinput", label: track.label }]; },
    async getUserMedia() { return { getTracks: () => [track], getAudioTracks: () => [track] }; },
  };
  window.AudioContext = SilentAudioContext;
  try {
    await dom.click(dom.byText("Devices"));
    await dom.flush();
    await dom.click(dom.byLabel("Test microphone"));
    await dom.flush();
    assert.match(dom.text(), /Listening for input…/);
    // The meter samples every 80 ms; two seconds of zeros is 25 samples.
    for (let tick = 0; tick < 25; tick += 1) await dom.flush(100);
    assert.match(dom.text(), /C920 PRO HD Webcam Analog Stereo is sending no sound\. It may be muted/);
    exactSamples = 0.25;
    await dom.flush(100);
    assert.match(dom.text(), /Input detected/);
    assert.doesNotMatch(dom.text(), /sending no sound/);
  } finally {
    delete window.AudioContext;
    await dom.unmount();
  }
});

test("device settings show the OS speech recognizer, why it can't be used and the offline choice", async () => {
  function SettingsHarness() {
    const [settings, setSettings] = React.useState(settingsModule.DEFAULT_APP_SETTINGS);
    return React.createElement(settingsPopoverModule.default, {
      onChange: (path, value) => setSettings((current) => settingsModule.updateSetting(current, path, value)),
      onClose() {}, onResetAll() {}, open: true, settings,
    });
  }
  const saved = [];
  let checks = 0;
  const macos = {
    engine: "system",
    system: { id: "macos", name: "macOS speech recognition", available: false, reason: "Speech recognition is off for Raticode. Turn it on in System Settings > Privacy & Security > Speech Recognition." },
    offline: { name: "Raticode's offline speech model", installed: false, downloadMb: 475 },
  };
  const dom = await mountReact(React.createElement(SettingsHarness), createFetchMock([
    jsonResponse("/api/devices", { experimental_network: false, enabled: true, peers: [] }),
    (url, options = {}) => {
      if (!url.startsWith("/api/chat/transcribe/engines")) return null;
      if (options.method === "POST") {
        saved.push(JSON.parse(options.body));
        return { ok: true, status: 200, json: async () => ({ saved: true, engine: "offline" }) };
      }
      checks += 1;
      if (checks > 1) assert.equal(url, "/api/chat/transcribe/engines?refresh=1");
      return { ok: true, status: 200, json: async () => macos };
    },
  ]));
  try {
    await dom.click(dom.byText("Devices"));
    await dom.flush();
    await dom.flush();
    assert.match(dom.text(), /Speech recognition is off for Raticode\. .*Until then, dictation uses Raticode's offline model if it's installed\./);
    const select = dom.byLabel("Speech recognition");
    assert.deepEqual([...select.options].map((option) => option.textContent), ["Built into macOS", "Raticode offline model"]);
    await dom.change(select, "offline");
    await dom.flush();
    assert.deepEqual(saved, [{ engine: "offline" }]);
    assert.match(dom.text(), /Raticode's offline speech model isn't downloaded yet\. It's about 475 MB/);
    assert.ok(dom.byText("Download offline model"));
    await dom.click(dom.byText("Check again"));
    await dom.flush();
    assert.equal(checks, 2);
  } finally { await dom.unmount(); }

  const linux = await mountReact(React.createElement(SettingsHarness), createFetchMock([
    jsonResponse("/api/devices", { experimental_network: false, enabled: true, peers: [] }),
    jsonResponse("/api/chat/transcribe/engines", {
      engine: "system",
      system: { id: "", name: "", available: false, reason: "Linux doesn't include a speech recognizer, so Raticode uses its own offline model." },
      offline: { name: "Raticode's offline speech model", installed: true, downloadMb: 475 },
    }),
  ]));
  try {
    await linux.click(linux.byText("Devices"));
    await linux.flush();
    await linux.flush();
    // Nothing to choose on Linux: it says so instead of offering a recognizer it doesn't have.
    assert.equal(allElements(linux.container).some((node) => node.getAttribute?.("aria-label") === "Speech recognition"), false);
    assert.match(linux.text(), /Linux doesn't include a speech recognizer, so Raticode uses its own offline model\./);
    assert.match(linux.text(), /Raticode's offline speech model is installed\./);
    assert.equal(allElements(linux.container).some((node) => node.textContent === "Download offline model"), false);
    assert.equal(allElements(linux.container).some((node) => node.textContent === "Test speech recognition"), false);
  } finally { await linux.unmount(); }

  // Someone who had the old Vosk model is told it was replaced; nothing downloads by itself.
  const replaced = await mountReact(React.createElement(SettingsHarness), createFetchMock([
    jsonResponse("/api/devices", { experimental_network: false, enabled: true, peers: [] }),
    jsonResponse("/api/chat/transcribe/engines", {
      engine: "system",
      system: { id: "", name: "", available: false, reason: "Linux doesn't include a speech recognizer, so Raticode uses its own offline model." },
      offline: { name: "Raticode's offline speech model", installed: false, downloadMb: 475, replaced: true, model: "NVIDIA Nemotron 3.5 ASR Streaming 0.6B", license: "OpenMDW License 1.1" },
    }),
  ]));
  try {
    await replaced.click(replaced.byText("Devices"));
    await replaced.flush();
    await replaced.flush();
    assert.match(replaced.text(), /Raticode's offline speech model was replaced by a newer one, so the old model was removed\. Download the new one \(about 475 MB\)/);
    assert.match(replaced.text(), /The model is NVIDIA Nemotron 3\.5 ASR Streaming 0\.6B, under the OpenMDW License 1\.1\. It recognizes English and other languages on its own\./);
    assert.ok(replaced.byText("Download offline model"));
  } finally { await replaced.unmount(); }

  // Windows: a hint that the downloaded model replaces the Windows recognizer.
  const windows = await mountReact(React.createElement(SettingsHarness), createFetchMock([
    jsonResponse("/api/devices", { experimental_network: false, enabled: true, peers: [] }),
    jsonResponse("/api/chat/transcribe/engines", {
      engine: "system",
      system: { id: "windows", name: "Windows speech recognition", available: true, language: "en-US" },
      offline: { name: "Raticode's offline speech model", installed: false, downloadMb: 475 },
    }),
  ]));
  try {
    await windows.click(windows.byText("Devices"));
    await windows.flush();
    await windows.flush();
    assert.deepEqual([...windows.byLabel("Speech recognition").options].map((option) => option.textContent), ["Built into Windows", "Raticode offline model"]);
    assert.match(windows.text(), /more accurate than the Windows recognizer\. Once it's downloaded, dictation uses it\./);
  } finally { await windows.unmount(); }
});

test("device settings download the offline model with progress and test macOS speech recognition", async () => {
  function SettingsHarness() {
    const [settings, setSettings] = React.useState(settingsModule.DEFAULT_APP_SETTINGS);
    return React.createElement(settingsPopoverModule.default, {
      onChange: (path, value) => setSettings((current) => settingsModule.updateSetting(current, path, value)),
      onClose() {}, onResetAll() {}, open: true, settings,
    });
  }
  const name = "Raticode's offline speech model";
  const mb = 1024 * 1024;
  const progress = [
    { name, installed: false, downloadMb: 475, download: { state: "downloading", receivedBytes: 50 * mb, totalBytes: 125 * mb } },
    { name, installed: false, downloadMb: 475, download: { state: "installing", receivedBytes: 125 * mb, totalBytes: 125 * mb } },
    { name, installed: true, downloadMb: 475 },
  ];
  const requests = [];
  let polls = 0;
  const dom = await mountReact(React.createElement(SettingsHarness), createFetchMock([
    jsonResponse("/api/devices", { experimental_network: false, enabled: true, peers: [] }),
    (url, options = {}) => {
      if (url === "/api/chat/transcribe/engines") {
        return { ok: true, status: 200, json: async () => ({
          engine: "system",
          system: { id: "macos", name: "macOS speech recognition", available: true, language: "en-US", reason: "macOS asks for permission to use speech recognition the first time you dictate." },
          offline: { name, installed: false, downloadMb: 475, download: { state: "failed", receivedBytes: 0, totalBytes: 0, error: "The local speech model couldn't be downloaded: the download server's security certificate couldn't be verified." } },
        }) };
      }
      if (url === "/api/chat/transcribe/model" && options.method === "POST") {
        requests.push(url);
        return { ok: true, status: 202, json: async () => ({ name, installed: false, downloadMb: 475, download: { state: "starting", receivedBytes: 0, totalBytes: 0 } }) };
      }
      if (url === "/api/chat/transcribe/model") {
        const status = progress[Math.min(polls, progress.length - 1)];
        polls += 1;
        return { ok: true, status: 200, json: async () => status };
      }
      if (url === "/api/chat/transcribe/engines/test") {
        requests.push(url);
        return { ok: true, status: 200, json: async () => ({
          test: { id: "macos", ok: true, message: "macOS speech recognition works (en-US). Speech is recognized on this Mac." },
          engine: "system",
          system: { id: "macos", name: "macOS speech recognition", available: true, language: "en-US" },
          offline: progress[2],
        }) };
      }
      return null;
    },
  ]));
  try {
    // Fake timers: each poll is one interval tick, and its answer a few promise turns later.
    await dom.click(dom.byText("Devices"));
    await dom.flush();
    await dom.flush();
    // A failed download keeps its reason on screen and offers to try again.
    assert.match(dom.text(), /security certificate couldn't be verified/);
    await dom.click(dom.byText("Try the download again"));
    await dom.flush();
    assert.deepEqual(requests, ["/api/chat/transcribe/model"]);
    assert.match(dom.text(), /Starting the download of Raticode's offline speech model…/);
    await dom.flush(800);
    for (let step = 0; step < 6; step += 1) await dom.flush();
    assert.match(dom.text(), /Downloading Raticode's offline speech model… 50 of 125 MB/);
    const bar = allElements(dom.container).find((node) => node.getAttribute?.("role") === "progressbar");
    assert.equal(bar.getAttribute("aria-valuenow"), "40");
    await dom.flush(800);
    for (let step = 0; step < 6; step += 1) await dom.flush();
    assert.match(dom.text(), /Checking and installing Raticode's offline speech model…/);
    await dom.flush(800);
    for (let step = 0; step < 6; step += 1) await dom.flush();
    assert.match(dom.text(), /Raticode's offline speech model is installed\./);
    const settledPolls = polls;
    await dom.flush(800);
    assert.equal(polls, settledPolls, "polling stops once the model is installed");

    await dom.click(dom.byText("Test speech recognition"));
    await dom.flush();
    await dom.flush();
    assert.deepEqual(requests, ["/api/chat/transcribe/model", "/api/chat/transcribe/engines/test"]);
    assert.match(dom.text(), /macOS speech recognition works \(en-US\)\. Speech is recognized on this Mac\./);
  } finally { await dom.unmount(); }
});

