test("shared dialogs trap focus, close with Escape, and restore focus to the opener", async () => {
  function DialogHarness() {
    const [open, setOpen] = React.useState(false);
    return React.createElement(
      React.Fragment,
      null,
      React.createElement(
        "button",
        { "aria-label": "Open test dialog", type: "button", onClick: () => setOpen(true) },
        "Open",
      ),
      open
        ? React.createElement(
            dialogModule.Dialog,
            {
              description: "Dialog focus behavior",
              onClose: () => setOpen(false),
              title: "Test dialog",
            },
            React.createElement(
              "button",
              { "aria-label": "First dialog action", type: "button" },
              "First",
            ),
            React.createElement(
              "button",
              { "aria-label": "Last dialog action", type: "button" },
              "Last",
            ),
          )
        : null,
    );
  }

  const dom = await mountReact(
    React.createElement(DialogHarness),
    createFetchMock([]),
  );
  const opener = dom.byLabel("Open test dialog");
  await dom.focus(opener);
  await dom.click(opener);

  const dialog = allElements(dom.container).find(
    (element) => element.getAttribute?.("role") === "dialog",
  );
  assert.ok(dialog);
  assert.equal(dialog.getAttribute("aria-modal"), "true");
  assert.ok(dialog.getAttribute("aria-labelledby"));
  assert.ok(dialog.getAttribute("aria-describedby"));

  const first = dom.byLabel("First dialog action");
  const last = dom.byLabel("Last dialog action");
  assert.equal(document.activeElement, first);

  await dom.focus(last);
  await dom.dispatchWindow("keydown", { key: "Tab" });
  assert.equal(document.activeElement, first);

  await dom.focus(first);
  await dom.dispatchWindow("keydown", { key: "Tab", shiftKey: true });
  assert.equal(document.activeElement, last);

  await dom.dispatchWindow("keydown", { key: "Escape" });
  assert.equal(document.activeElement, opener);
  assert.equal(
    allElements(dom.container).some((element) => element.getAttribute?.("role") === "dialog"),
    false,
  );

  await dom.unmount();
});

test("an approval with options shows one button per option and sends the typed reply", async () => {
  const decisions = [];
  const approval = {
    workflowId: "demo",
    runId: "run-1",
    nodeId: "channel",
    message: "Where should this build go?",
    status: "pending",
    approvers: [],
    options: ["Stable", "Beta", "Cancel"],
    rejectOptions: ["Cancel"],
    reply: "required",
  };
  const dom = await mountReact(
    React.createElement(canvasModule.ApprovalDecisionOverlay, {
      approval,
      node: { id: "channel", label: "Channel" },
      onDecideApproval: (...args) => decisions.push(args),
    }),
    createFetchMock([]),
  );
  assert.equal(dom.allByTitle("Approve pending approval").length, 0);
  assert.equal(dom.allByTitle("Reject pending approval").length, 0);
  const beta = dom.byTitle("Answer Beta");
  assert.ok(dom.byTitle("Answer Cancel (counts as a rejection)"));
  // A required reply keeps the answers disabled until something is typed.
  assert.equal(reactProps(beta).disabled, true);
  await dom.change(dom.controlAfterLabel("Reply (required)"), "Internal testers only");
  assert.equal(reactProps(dom.byTitle("Answer Beta")).disabled, false);
  await dom.click(dom.byTitle("Answer Beta"));
  assert.equal(decisions.length, 1);
  const [sent, decision, , , answer] = decisions[0];
  assert.equal(sent, approval);
  assert.equal(decision, "approved");
  assert.deepEqual(answer, { choice: "Beta", reply: "Internal testers only" });
  await dom.unmount();
});

