test("list and name/value node fields edit as rows, with Edit as JSON as the fallback", async () => {
  const mutations = [];
  const node = (id, type, configuration) => ({
    id,
    label: id,
    type,
    configuration,
    execution: { allow_fail: false, max_concurrency: 1, retry_count: 0, retry_delay_ms: 1000 },
    authoredFields: { type: { value: type } },
    bindings: [],
    needs: [],
    diagnostics: [],
  });
  const rattishDocument = {
    workflowId: "rows",
    source: "Rattish: 1\nWorkflow:\n  name: Rows\n",
    workflow: { name: "Rows", fields: { name: { value: "Rows" } } },
    nodeContracts: [
      {
        nodeType: "http-request",
        configurationSchema: {
          type: "object",
          properties: {
            url: { type: "string" },
            headers: { type: "object", additionalProperties: { type: "string" } },
            retry: { type: "object", properties: { attempts: { type: "integer" } }, additionalProperties: false },
          },
        },
        defaults: {},
      },
      {
        nodeType: "approval-gate",
        configurationSchema: {
          type: "object",
          properties: {
            message: { type: "string" },
            approvers: { type: "array", items: { type: "string" } },
          },
        },
        defaults: {},
      },
    ],
    graph: {
      nodes: [
        node("fetch", "http-request", { url: "https://example.com", headers: {}, retry: { attempts: 1 } }),
        node("gate", "approval-gate", { message: "OK?", approvers: ["ann", "bo"] }),
      ],
      edges: [],
    },
  };
  const workflow = appModule.rattishGraphWorkflow(
    { ...workflowFixture({ id: "rows", name: "Rows" }), sourceFormat: "rattish", nodes: [], edges: [] },
    rattishDocument,
  );
  // The backend's answer: the same document with the saved field in the node's configuration.
  let saved = rattishDocument;
  const dom = await mountReact(
    React.createElement(DagCanvasHarness, {
      workflow,
      rattishDocument,
      onRattishMutation(next) {
        mutations.push(next);
        const [{ target, field, value }] = next;
        saved = {
          ...saved,
          graph: {
            ...saved.graph,
            nodes: saved.graph.nodes.map((candidate) =>
              candidate.id === target.node
                ? { ...candidate, configuration: { ...candidate.configuration, [field]: value } }
                : candidate,
            ),
          },
        };
        return Promise.resolve(saved);
      },
      onWorkflowChange() {},
    }),
    createFetchMock([]),
  );
  const textareas = () => allElements(dom.container).filter((element) => element.tagName === "TEXTAREA");
  try {
    await dom.pointer(dom.ancestor(dom.byText("fetch"), "ARTICLE"), "onPointerDown");
    await dom.flush();
    await dom.click(dom.byText("Action"));
    await dom.flush();
    // Headers is a name/value editor, not a JSON box; Retry has its own fields and stays JSON.
    assert.match(dom.text(), /No headers yet/);
    assert.equal(textareas().length, 1);
    await dom.click(dom.byExactText("Add header"));
    await dom.flush();
    assert.match(dom.text(), /Name.*Value/);
    assert.equal(document.activeElement, dom.byLabel("Header 1 name"));
    await dom.change(dom.byLabel("Header 1 name"), "Accept");
    await dom.change(dom.byLabel("Header 1 value"), "application/json");
    // Moving between the row's own inputs doesn't save; leaving the editor does.
    await React.act(async () => {
      reactProps(dom.byLabel("Header 1 name")).onBlur({ relatedTarget: dom.byLabel("Header 1 value") });
    });
    assert.deepEqual(mutations, []);
    await dom.blur(dom.byLabel("Header 1 value"));
    await dom.flush();
    assert.deepEqual(mutations, [
      [{ kind: "set_field", target: { node: "fetch" }, field: "headers", value: { Accept: "application/json" } }],
    ]);

    // A repeated or missing name is flagged on its row and nothing is saved.
    await dom.click(dom.byExactText("Add header"));
    await dom.flush();
    await dom.change(dom.byLabel("Header 2 name"), "Accept");
    assert.equal(dom.byLabel("Header 2 name").getAttribute("aria-invalid"), "true");
    assert.match(dom.text(), /Accept is already used in row 1\./);
    await dom.blur(dom.byLabel("Header 2 name"));
    await dom.flush();
    assert.equal(mutations.length, 1);
    await dom.change(dom.byLabel("Header 2 name"), "");
    await dom.change(dom.byLabel("Header 2 value"), "orphan");
    assert.match(dom.text(), /Add a name for this value\./);
    await dom.click(dom.byLabel("Remove header 2"));
    await dom.flush();
    assert.doesNotMatch(dom.text(), /Add a name|already used/);
    assert.equal(mutations.length, 1);

    // Approvers: one row each, with Add, Remove and Move.
    await dom.pointer(dom.ancestor(dom.byText("gate"), "ARTICLE"), "onPointerDown");
    await dom.flush();
    await dom.click(dom.byText("Action"));
    await dom.flush();
    assert.equal(dom.byLabel("Approver 1").value, "ann");
    assert.equal(dom.byLabel("Approver 2").value, "bo");
    assert.equal(reactProps(dom.byLabel("Move approver 1 up")).disabled, true);
    await dom.click(dom.byLabel("Move approver 2 up"));
    await dom.flush();
    assert.deepEqual(mutations.at(-1), [
      { kind: "set_field", target: { node: "gate" }, field: "approvers", value: ["bo", "ann"] },
    ]);
    assert.equal(document.activeElement, dom.byLabel("Move approver 1 down"));
    await dom.click(dom.byExactText("Add approver"));
    await dom.flush();
    await dom.change(dom.byLabel("Approver 3"), "cy");
    await dom.keyDown(dom.byLabel("Approver 3"), "Enter");
    await dom.flush();
    assert.deepEqual(mutations.at(-1)[0].value, ["bo", "ann", "cy"]);
    await dom.click(dom.byLabel("Remove approver 1"));
    await dom.flush();
    assert.deepEqual(mutations.at(-1)[0].value, ["ann", "cy"]);

    // Edit as JSON shows the JSON box with the same value.
    const jsonSwitch = dom.byLabel("Edit Approvers as JSON");
    assert.equal(jsonSwitch.getAttribute("role"), "switch");
    assert.equal(jsonSwitch.getAttribute("aria-checked"), "false");
    assert.equal(textareas().length, 0);
    await dom.click(jsonSwitch);
    await dom.flush();
    assert.equal(dom.byLabel("Edit Approvers as JSON").getAttribute("aria-checked"), "true");
    assert.equal(textareas().length, 1);
    assert.equal(textareas()[0].value, JSON.stringify(["ann", "cy"], null, 2));
  } finally {
    await dom.unmount();
  }
});

test("each node field shows its contract description under the label, linked to the control", async () => {
  const contract = (type) => {
    const document = JSON.parse(fs.readFileSync(path.join(repoRoot, "rattish/contracts", `${type}.json`), "utf8"));
    return { nodeType: type, configurationSchema: document.configuration_schema, defaults: document.defaults };
  };
  const node = (id, type, configuration) => ({
    id,
    label: id,
    type,
    configuration,
    execution: { allow_fail: false, max_concurrency: 1, retry_count: 0, retry_delay_ms: 1000 },
    authoredFields: { type: { value: type } },
    bindings: [],
    needs: [],
    diagnostics: [],
  });
  const rattishDocument = {
    workflowId: "help",
    source: "Rattish: 1\nWorkflow:\n  name: Help\n",
    workflow: { name: "Help", fields: { name: { value: "Help" } } },
    nodeContracts: [contract("http-request"), contract("delete-file"), contract("local-search")],
    graph: {
      nodes: [
        node("fetch", "http-request", { url: "https://example.com", headers: {}, response_mode: "auto" }),
        node("tidy", "delete-file", { path: "old.txt", use_trash: true }),
        node("lookup", "local-search", { index_path: "index", query: "rats", top_k: 5 }),
      ],
      edges: [],
    },
  };
  const workflow = appModule.rattishGraphWorkflow(
    { ...workflowFixture({ id: "help", name: "Help" }), sourceFormat: "rattish", nodes: [], edges: [] },
    rattishDocument,
  );
  const dom = await mountReact(
    React.createElement(DagCanvasHarness, { workflow, rattishDocument, onWorkflowChange() {} }),
    createFetchMock([]),
  );
  const byId = (id) => allElements(dom.container).find((element) => element.getAttribute?.("id") === id);
  // The help line's element, and the control (or row group) it describes.
  const described = (help) => {
    const line = dom.byExactText(help);
    const id = line.getAttribute("id");
    assert.ok(id, `${help} has an id`);
    const control = allElements(dom.container).find((element) =>
      (element.getAttribute?.("aria-describedby") ?? "").split(" ").includes(id),
    );
    assert.ok(control, `a control is described by ${help}`);
    return control;
  };
  const nameOf = (control) => byId(control.getAttribute("aria-labelledby")).textContent;
  const openAction = async (nodeId) => {
    await dom.pointer(dom.ancestor(dom.byText(nodeId), "ARTICLE"), "onPointerDown");
    await dom.flush();
    await dom.click(dom.byText("Action"));
    await dom.flush();
  };
  try {
    await openAction("fetch");
    assert.match(dom.text(), /String HTTP headers\./);
    const headers = described("String HTTP headers.");
    assert.equal(headers.tagName, "FIELDSET");
    assert.equal(headers.getAttribute("data-rattish-rows"), "map");

    const url = described("HTTP or HTTPS endpoint.");
    assert.equal(url.tagName, "INPUT");
    assert.equal(nameOf(url), "Url");
    const mode = described("Response interpretation.");
    assert.equal(mode.tagName, "SELECT");
    assert.equal(nameOf(mode), "Response Mode");
    const body = described("Text request body.");
    assert.equal(body.tagName, "TEXTAREA");
    assert.equal(nameOf(body), "Body");
    // Retry has its own fields, so it opens in the JSON box.
    const retry = described("Attempt count, backoff, and retry-on-statuses map.");
    assert.equal(retry.tagName, "TEXTAREA");
    assert.equal(nameOf(retry), "Retry");

    await openAction("tidy");
    const trash = described("Use trash rather than permanent removal.");
    assert.equal(trash.getAttribute("type"), "checkbox");
    assert.equal(nameOf(trash), "Use Trash");

    await openAction("lookup");
    const topK = described("Maximum returned results.");
    assert.equal(topK.tagName, "INPUT");
    assert.equal(topK.value, "5");
  } finally {
    await dom.unmount();
  }
});

test("MCP tool nodes pick a server from Rem's list and a tool the server lists", async () => {
  const mutations = [];
  const node = (id, configuration) => ({
    id,
    label: id,
    type: "mcp-tool",
    configuration,
    execution: { allow_fail: false, max_concurrency: 1, retry_count: 0, retry_delay_ms: 1000 },
    authoredFields: { type: { value: "mcp-tool" } },
    bindings: [],
    needs: [],
    diagnostics: [],
  });
  const defaults = { arguments: {}, sandbox: "on", network: [], working_dir: "." };
  const document = {
    workflowId: "mcp-call",
    source: "Rattish: 1\nWorkflow:\n  name: MCP call\n",
    workflow: { name: "MCP call", fields: { name: { value: "MCP call" } } },
    nodeContracts: [
      {
        nodeType: "mcp-tool",
        configurationSchema: {
          type: "object",
          properties: {
            server: { type: "string" },
            tool: { type: "string" },
            arguments: { type: ["object", "string"] },
          },
        },
        defaults,
      },
    ],
    graph: {
      nodes: [
        node("search", { ...defaults, server: "docs", tool: "search", network: ["api.example.com"] }),
        node("broken", { ...defaults, server: "flaky", tool: "lookup", sandbox: "off" }),
      ],
      edges: [],
    },
  };
  const workflow = appModule.rattishGraphWorkflow(
    { ...workflowFixture({ id: "mcp-call", name: "MCP call" }), sourceFormat: "rattish", nodes: [], edges: [] },
    document,
  );
  const fetchMock = createFetchMock([
    (url) =>
      String(url).endsWith("/rem-resources")
        ? {
            ok: true,
            status: 200,
            json: async () => ({
              skillsDir: "",
              skills: [],
              mcpServers: [
                { name: "docs", type: "stdio", command: "docs-mcp", args: [] },
                { name: "flaky", type: "http", url: "https://flaky.example/mcp" },
              ],
            }),
          }
        : null,
    (url) =>
      String(url).includes("/rem-resources/mcp-tools?name=docs")
        ? {
            ok: true,
            status: 200,
            json: async () => ({
              server: "docs",
              tools: [
                {
                  name: "search",
                  title: "Search the docs",
                  description: "Finds pages by words.",
                  inputSchema: {
                    type: "object",
                    properties: { query: { type: "string" }, limit: { type: "integer" } },
                    required: ["query"],
                  },
                },
                { name: "fetch", inputSchema: { type: "object" } },
              ],
            }),
          }
        : null,
    (url) =>
      String(url).includes("/rem-resources/mcp-tools?name=flaky")
        ? { ok: false, status: 502, json: async () => ({ error: "Couldn't reach the MCP server." }) }
        : null,
  ]);
  const dom = await mountReact(
    React.createElement(DagCanvasHarness, {
      workflow,
      rattishDocument: document,
      onRattishMutation(next) {
        mutations.push(next);
        return Promise.resolve(null);
      },
      onWorkflowChange() {},
    }),
    fetchMock,
  );

  // The canvas names the server and tool without opening the node.
  assert.match(dom.text(), /docs · search/);
  await dom.pointer(dom.ancestor(dom.byText("search"), "ARTICLE"), "onPointerDown");
  await dom.flush();
  await dom.click(dom.byText("Action"));
  await dom.flush();
  await dom.flush();
  await dom.flush();
  const server = dom.controlAfterLabel("Server");
  assert.equal(server.tagName, "SELECT");
  assert.equal(reactProps(server).value, "docs");
  assert.match(dom.text(), /flaky · HTTP/);
  const tool = dom.controlAfterLabel("Tool");
  assert.equal(tool.tagName, "SELECT");
  assert.match(dom.text(), /Search the docs/);
  assert.match(dom.text(), /Finds pages by words/);
  assert.match(dom.text(), /Arguments: query \(string\), limit\? \(integer\)/);
  assert.match(dom.text(), /Calls one tool on a server from Rem's MCP server list/);
  // The tools are listed with the step's own network, as a run would start the server.
  assert.ok(
    fetchMock.calls.some((call) =>
      String(call.url).includes("/rem-resources/mcp-tools?name=docs&network=api.example.com"),
    ),
  );
  await dom.change(tool, "fetch");
  assert.deepEqual(mutations.at(-1), [
    { kind: "set_field", target: { node: "search" }, field: "tool", value: "fetch" },
  ]);

  // A server that can't be listed keeps a typed tool name and says why.
  await dom.pointer(dom.ancestor(dom.byText("broken"), "ARTICLE"), "onPointerDown");
  await dom.flush();
  await dom.click(dom.byText("Action"));
  await dom.flush();
  await dom.flush();
  await dom.flush();
  assert.equal(dom.controlAfterLabel("Tool").tagName, "INPUT");
  assert.match(dom.text(), /Couldn't reach the MCP server/);
  assert.ok(
    fetchMock.calls.some((call) => String(call.url).includes("name=flaky&sandbox=off")),
  );
  await dom.unmount();
});

