function jsonResponse(url, payload, { method = "GET", ok = true, status = ok ? 200 : 500 } = {}) {
  return (requestUrl, options = {}) => {
    if (requestUrl !== url || (options.method ?? "GET") !== method) return null;
    return {
      ok,
      status,
      json: async () => payload,
    };
  };
}

function createDeferred() {
  let resolve, reject;
  const promise = new Promise((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

function streamResponse(chunks) {
  return (url) => ({
    ok: true,
    status: 200,
    body: {
      getReader() {
        let index = 0;
        return {
          async read() {
            if (index >= chunks.length) return { done: true, value: undefined };
            const value = new TextEncoder().encode(chunks[index]);
            index += 1;
            return { done: false, value };
          },
        };
      },
    },
    json: async () => ({}),
    url,
  });
}

function controlledStreamResponse(chunks) {
  const pendingReads = chunks.map(() => createDeferred());
  return {
    releaseNext() {
      const nextRead = pendingReads.find((deferred) => !deferred.released);
      if (!nextRead) return;
      nextRead.released = true;
      nextRead.resolve();
    },
    response(url) {
      return {
        ok: true,
        status: 200,
        body: {
          getReader() {
            let index = 0;
            return {
              async read() {
                if (index >= chunks.length) return { done: true, value: undefined };
                const deferred = pendingReads[index];
                await deferred.promise;
                const value = new TextEncoder().encode(chunks[index]);
                index += 1;
                return { done: false, value };
              },
            };
          },
        },
        json: async () => ({}),
        url,
      };
    },
  };
}

function createFetchMock(handlers) {
  const calls = [];
  const fetchMock = async (url, options = {}) => {
    calls.push({ url, options });
    for (const handler of handlers) {
      const response = handler(url, options);
      if (response) return response;
    }
    return { ok: true, status: 200, json: async () => ({}) };
  };
  fetchMock.calls = calls;
  return fetchMock;
}

async function exerciseDialogFamily(renderDialog, desktop = {}) {
  function DialogFamilyHarness() {
    const [open, setOpen] = React.useState(false);
    return React.createElement(
      React.Fragment,
      null,
      React.createElement(
        "button",
        {
          "aria-label": "Open dialog family",
          onClick: () => setOpen(true),
          type: "button",
        },
        "Open",
      ),
      open ? renderDialog(() => setOpen(false)) : null,
    );
  }

  const dom = await mountReact(
    React.createElement(DialogFamilyHarness),
    createFetchMock([]),
    { desktop },
  );
  const opener = dom.byLabel("Open dialog family");
  await dom.focus(opener);
  await dom.click(opener);
  await dom.flush();

  const dialog = allElements(dom.container).find(
    (element) => element.getAttribute?.("role") === "dialog",
  );
  assert.ok(dialog, "Expected the family to render a dialog");
  assert.equal(dialog.getAttribute("aria-modal"), "true");
  assert.ok(dialog.getAttribute("aria-labelledby"));
  assert.ok(dialog.getAttribute("aria-describedby"));
  assert.equal(dialog.contains(document.activeElement), true, "Initial focus escaped the dialog");

  const focusable = allElements(dialog).filter(
    (element) =>
      !element.disabled &&
      ["BUTTON", "INPUT", "SELECT", "TEXTAREA"].includes(element.tagName),
  );
  assert.ok(focusable.length > 0, "Expected at least one focusable dialog control");
  const first = focusable[0];
  const last = focusable.at(-1);

  await dom.focus(last);
  await dom.dispatchWindow("keydown", { key: "Tab" });
  assert.equal(document.activeElement, first, "Tab did not wrap to the first control");

  await dom.focus(first);
  await dom.dispatchWindow("keydown", { key: "Tab", shiftKey: true });
  assert.equal(document.activeElement, last, "Shift+Tab did not wrap to the last control");

  await dom.dispatchWindow("keydown", { key: "Escape" });
  assert.equal(document.activeElement, opener, "Focus did not return to the opener");
  assert.equal(
    allElements(dom.container).some((element) => element.getAttribute?.("role") === "dialog"),
    false,
    "Escape did not close the dialog",
  );

  await dom.unmount();
}

// Swarms and Second Brain are experimental plugins, so tests that open them
// from the activity rail turn them on first. Rem is always available.
const EXPERIMENTAL_PLUGINS_ON = { swarms: true, "second-brain": true };

function experimentalPluginStorage() {
  return { [settingsModule.SETTINGS_STORAGE_KEY]: JSON.stringify({ plugins: { enabled: EXPERIMENTAL_PLUGINS_ON } }) };
}

async function mountReact(element, fetchMock, { browser, desktop = {}, storage = {}, updates } = {}) {
  const dom = installTestDom();
  const { createRoot } = require("react-dom/client");
  globalThis.IS_REACT_ACT_ENVIRONMENT = true;
  globalThis.fetch = fetchMock;
  globalThis.window.fetch = fetchMock;
  globalThis.window.goferApiBaseUrl = undefined;
  globalThis.window.goferBrowser = browser;
  globalThis.window.goferDesktop = desktop;
  globalThis.window.goferUpdates = updates;
  for (const [key, value] of Object.entries(storage)) {
    globalThis.window.localStorage.setItem(key, value);
  }
  // Screens ask in ConfirmDialog; a native box would mean a screen went back to it.
  globalThis.window.confirm = (message) => assert.fail(`Raticode asks in its own dialog, not window.confirm: ${message}`);
  globalThis.window.requestAnimationFrame = (callback) => {
    callback();
    return 1;
  };
  globalThis.window.cancelAnimationFrame = () => {};

  const container = document.createElement("div");
  document.body.appendChild(container);
  const root = createRoot(container);
  await React.act(async () => {
    root.render(element);
  });

  return {
    container,
    fetchCalls: fetchMock.calls,
    async change(elementNode, value) {
      await React.act(async () => {
        elementNode.value = value;
        elementNode.checked = Boolean(value);
        reactProps(elementNode).onChange?.({ target: elementNode, currentTarget: elementNode });
      });
    },
    async click(elementNode) {
      await React.act(async () => {
        reactProps(elementNode).onClick?.(testEvent(elementNode));
      });
    },
    async blur(elementNode) {
      await React.act(async () => {
        reactProps(elementNode).onBlur?.(testEvent(elementNode));
        elementNode.blur();
      });
    },
    async dispatchWindow(type, patch = {}) {
      await React.act(async () => {
        const event = Object.assign(new TestEvent(type), {
          defaultPrevented: false,
          preventDefault() {
            this.defaultPrevented = true;
          },
          stopPropagation() {},
          ...patch,
        });
        for (const listener of document.listeners[type] ?? []) {
          listener(event);
        }
        await Promise.resolve();
      });
    },
    async flush(ms = 0) {
      await React.act(async () => {
        if (ms > 0) {
          dom.runTimers(ms);
        }
        await Promise.resolve();
        await Promise.resolve();
      });
    },
    async focus(elementNode) {
      await React.act(async () => {
        elementNode.focus();
        reactProps(elementNode).onFocus?.(testEvent(elementNode));
      });
    },
    async keyDown(elementNode, key, patch = {}) {
      await React.act(async () => {
        reactProps(elementNode).onKeyDown?.(testEvent(elementNode, { key, ...patch }));
      });
    },
    async pointer(elementNode, handlerName, patch = {}) {
      await React.act(async () => {
        reactProps(elementNode)[handlerName]?.(testEvent(elementNode, patch));
      });
    },
    async unmount() {
      await React.act(async () => {
        root.unmount();
      });
      dom.restore();
    },
    allByTitle(title) {
      return allElements(container).filter((node) => node.getAttribute?.("title") === title);
    },
    ancestor(elementNode, tagNameOrPredicate) {
      let current = elementNode;
      const matches =
        typeof tagNameOrPredicate === "function"
          ? tagNameOrPredicate
          : (node) => node.tagName === tagNameOrPredicate;
      while (current && !matches(current)) {
        current = current.parentNode;
      }
      assert.ok(current, "Unable to find matching ancestor");
      return current;
    },
    byText(text) {
      const match = allElements(container).find((node) =>
        directText(node).includes(text),
      );
      assert.ok(match, `Unable to find text: ${text}`);
      return match;
    },
    byExactText(text) {
      const match = allElements(container).find((node) => directText(node) === text);
      assert.ok(match, `Unable to find exact text: ${text}`);
      return match;
    },
    byTitle(title) {
      const match = allElements(container).find((node) => node.getAttribute?.("title") === title);
      assert.ok(match, `Unable to find title: ${title}`);
      return match;
    },
    byLabel(label) {
      const match = allElements(container).find((node) => node.getAttribute?.("aria-label") === label);
      assert.ok(match, `Unable to find aria-label: ${label}`);
      return match;
    },
    controlAfterLabel(labelText) {
      const label = allElements(container).find((node) =>
        node.tagName === "LABEL" && textOf(node).includes(labelText) && !isInactiveGraphDescendant(node),
      );
      assert.ok(label, `Unable to find label: ${labelText}`);
      const control = allElements(label).find((node) =>
        ["INPUT", "SELECT", "TEXTAREA"].includes(node.tagName),
      );
      assert.ok(control, `Unable to find control for label: ${labelText}`);
      return control;
    },
    first(tagName) {
      const match = allElements(container).find((node) => node.tagName === tagName.toUpperCase());
      assert.ok(match, `Unable to find ${tagName}`);
      return match;
    },
    selectWithOption(value) {
      const match = allElements(container).find(
        (node) => node.tagName === "SELECT" && [...(node.options ?? [])].some((option) => option.value === value),
      );
      assert.ok(match, `Unable to find select with option: ${value}`);
      return match;
    },
    text() {
      return textOf(container);
    },
  };
}

function isInactiveGraphDescendant(node) {
  for (let current = node; current; current = current.parentNode) {
    if (current.getAttribute?.("data-graph-active") === "false") return true;
  }
  return false;
}

function testEvent(target, patch = {}) {
  return {
    button: 0,
    buttons: 1,
    clientX: 0,
    clientY: 0,
    currentTarget: target,
    defaultPrevented: false,
    pointerId: 1,
    preventDefault() {
      this.defaultPrevented = true;
    },
    stopPropagation() {},
    target,
    ...patch,
  };
}

// An off button stays focusable (aria-disabled, not disabled) and says why in
// visible text that aria-describedby points at, not only in a tooltip.
function assertOffWithReason(dom, button, reason) {
  assert.equal(button.getAttribute("aria-disabled"), "true");
  assert.equal(button.getAttribute("disabled"), null);
  assert.notEqual(reactProps(button).disabled, true);
  assert.notEqual(button.getAttribute("title"), reason);
  button.focus();
  assert.equal(document.activeElement, button);
  const describedBy = button.getAttribute("aria-describedby");
  assert.ok(describedBy, "the off button names its reason line");
  const line = allElements(dom.container).find((node) => node.getAttribute?.("id") === describedBy);
  assert.ok(line, "the reason line is on the page");
  assert.equal(textOf(line), reason);
  assert.ok(dom.text().includes(reason));
  return line;
}

function reactProps(node) {
  const key = Object.keys(node).find((candidate) => candidate.startsWith("__reactProps$"));
  assert.ok(key, `No React props found on ${node.tagName ?? node.nodeName}`);
  return node[key];
}

function installTestDom() {
  const previousNavigatorDescriptor = Object.getOwnPropertyDescriptor(globalThis, "navigator");
  const previous = {
    document: globalThis.document,
    fetch: globalThis.fetch,
    HTMLElement: globalThis.HTMLElement,
    HTMLIFrameElement: globalThis.HTMLIFrameElement,
    Node: globalThis.Node,
    SVGElement: globalThis.SVGElement,
    window: globalThis.window,
  };
  const timers = [];
  const windowObject = {};
  const documentObject = new TestDocument(windowObject);
  Object.assign(windowObject, {
    document: documentObject,
    Event: TestEvent,
    HTMLElement: TestElement,
    HTMLIFrameElement: TestElement,
    Node: TestNode,
    SVGElement: TestElement,
    addEventListener: (...args) => documentObject.addEventListener(...args),
    dispatchEvent: event => {
      for (const listener of documentObject.listeners[event.type] ?? []) listener(event);
      return true;
    },
    clearInterval: (id) => clearTimer(timers, id),
    clearTimeout: (id) => clearTimer(timers, id),
    getComputedStyle: () => ({}),
    localStorage: createStorage(),
    navigator: { clipboard: { writeText: async () => {} }, userAgent: "node-test" },
    removeEventListener: (...args) => documentObject.removeEventListener(...args),
    scrollTo: () => {},
    setInterval: (callback, delay) => addTimer(timers, callback, delay, true),
    setTimeout: (callback, delay) => addTimer(timers, callback, delay, false),
  });

  globalThis.window = windowObject;
  globalThis.document = documentObject;
  globalThis.HTMLElement = TestElement;
  globalThis.HTMLIFrameElement = TestElement;
  globalThis.Node = TestNode;
  globalThis.SVGElement = TestElement;
  Object.defineProperty(globalThis, "navigator", {
    configurable: true,
    value: windowObject.navigator,
    writable: true,
  });

  return {
    restore() {
      Object.assign(globalThis, previous);
      if (previousNavigatorDescriptor) {
        Object.defineProperty(globalThis, "navigator", previousNavigatorDescriptor);
      } else {
        delete globalThis.navigator;
      }
    },
    runTimers(ms) {
      const runnable = timers.filter((timer) => timer.delay <= ms);
      for (const timer of runnable) {
        timer.callback();
        if (!timer.repeating) {
          clearTimer(timers, timer.id);
        }
      }
    },
  };
}

// Ids only ever go up, as in a browser, so clearing a timer that already ran can't hit another.
let nextTimerId = 1;

function addTimer(timers, callback, delay = 0, repeating = false) {
  const timer = { callback, delay, id: nextTimerId++, repeating };
  timers.push(timer);
  return timer.id;
}

function clearTimer(timers, id) {
  const index = timers.findIndex((timer) => timer.id === id);
  if (index >= 0) timers.splice(index, 1);
}

function createStorage() {
  const values = new Map();
  return {
    getItem: (key) => values.get(key) ?? null,
    key: (index) => [...values.keys()][index] ?? null,
    get length() { return values.size; },
    removeItem: (key) => values.delete(key),
    setItem: (key, value) => values.set(key, String(value)),
  };
}

class TestNode {
  constructor() {
    this.childNodes = [];
    this.listeners = {};
    this.parentNode = null;
  }

  appendChild(node) {
    return this.insertBefore(node, null);
  }

  contains(node) {
    let current = node;
    while (current) {
      if (current === this) return true;
      current = current.parentNode;
    }
    return false;
  }

  addEventListener(type, listener) {
    this.listeners[type] = [...(this.listeners[type] ?? []), listener];
  }

  removeEventListener(type, listener) {
    this.listeners[type] = (this.listeners[type] ?? []).filter((candidate) => candidate !== listener);
  }

  insertBefore(node, beforeNode) {
    if (node.parentNode) node.parentNode.removeChild(node);
    node.parentNode = this;
    if (beforeNode === null || beforeNode === undefined) {
      this.childNodes.push(node);
    } else {
      this.childNodes.splice(this.childNodes.indexOf(beforeNode), 0, node);
    }
    return node;
  }

  removeChild(node) {
    this.childNodes = this.childNodes.filter((child) => child !== node);
    node.parentNode = null;
    return node;
  }
}

function holdsTestNode(value) {
  return value instanceof TestNode || (Array.isArray(value) && value.some((item) => item instanceof TestNode));
}

function describeTestValue(value) {
  if (Array.isArray(value)) return `[${value.map(describeTestValue).join(", ")}]`;
  if (!(value instanceof TestNode)) return value === null || typeof value !== "object" ? String(value) : "[object]";
  const label = value.getAttribute?.("aria-label");
  return `<${String(value.nodeName).toLowerCase()}${label ? ` aria-label="${label}"` : ""}>`;
}

class TestElement extends TestNode {
  constructor(tagName, ownerDocument) {
    super();
    this.attributes = {};
    this.checked = false;
    this.disabled = false;
    this.localName = tagName;
    this.namespaceURI = "http://www.w3.org/1999/xhtml";
    this.nodeName = tagName.toUpperCase();
    this.nodeType = 1;
    this.ownerDocument = ownerDocument;
    this.style = { setProperty(name, value) { this[name] = value; }, removeProperty(name) { delete this[name]; } };
    this.tagName = tagName.toUpperCase();
    this.value = "";
  }

  blur() {
    this.ownerDocument.activeElement = null;
  }

  focus() {
    this.ownerDocument.activeElement = this;
  }

  querySelector() {
    return null;
  }

  hasPointerCapture() {
    return true;
  }

  getBoundingClientRect() {
    return {
      bottom: 640,
      height: 640,
      left: 0,
      right: 960,
      top: 0,
      width: 960,
    };
  }

  releasePointerCapture() {}

  setPointerCapture() {}

  getAttribute(name) {
    return this.attributes[name] ?? null;
  }

  removeAttribute(name) {
    delete this.attributes[name];
  }

  setAttribute(name, value) {
    this.attributes[name] = String(value);
    if (name === "value") this.value = String(value);
  }

  get textContent() {
    return this.childNodes.map((node) => node.textContent).join("");
  }

  get options() {
    return this.tagName === "SELECT"
      ? allElements(this).filter((node) => node.tagName === "OPTION")
      : undefined;
  }

  set textContent(value) {
    this.childNodes = [new TestText(value, this.ownerDocument)];
  }
}

class TestText extends TestNode {
  constructor(value, ownerDocument) {
    super();
    this.nodeName = "#text";
    this.nodeType = 3;
    this.nodeValue = String(value);
    this.ownerDocument = ownerDocument;
  }

  get textContent() {
    return this.nodeValue;
  }

  set textContent(value) {
    this.nodeValue = String(value);
  }
}

class TestDocument extends TestNode {
  constructor(defaultView) {
    super();
    this.activeElement = null;
    this.defaultView = defaultView;
    this.documentElement = new TestElement("html", this);
    this.body = new TestElement("body", this);
    this.nodeName = "#document";
    this.nodeType = 9;
    this.appendChild(this.documentElement);
    this.documentElement.appendChild(this.body);
  }

  createComment(value) {
    return new TestText(value, this);
  }

  createElement(tagName) {
    return new TestElement(tagName, this);
  }

  createElementNS(namespaceURI, tagName) {
    const element = new TestElement(tagName, this);
    element.namespaceURI = namespaceURI;
    return element;
  }

  createTextNode(value) {
    return new TestText(value, this);
  }

  getElementById() {
    return null;
  }
}

class TestEvent {}

function allElements(root) {
  const elements = [];
  for (const child of root.childNodes ?? []) {
    if (child.nodeType === 1) {
      elements.push(child);
      elements.push(...allElements(child));
    }
  }
  return elements;
}

function matchingLiveRegions(container, { politeness, role, text }) {
  return allElements(container).filter(
    (element) =>
      element.getAttribute?.("aria-live") === politeness &&
      element.getAttribute?.("role") === role &&
      textOf(element).includes(text),
  );
}

function directText(node) {
  return (node.childNodes ?? [])
    .filter((child) => child.nodeType === 3)
    .map((child) => child.textContent)
    .join("");
}

function textOf(node) {
  return node.textContent ?? "";
}

// The app asks before risky actions in its own dialog (ConfirmDialog.jsx), not window.confirm.
function confirmDialogIn(dom) {
  return allElements(dom.container).find(node => node.getAttribute?.("data-testid") === "confirm-dialog");
}

// Presses the open confirm dialog's action (accept) or "Keep as is", and returns what it asked.
async function answerConfirm(dom, accept) {
  for (let i = 0; i < 5 && !confirmDialogIn(dom); i++) await dom.flush();
  const dialog = confirmDialogIn(dom);
  assert.ok(dialog, "an in-app confirm dialog is open");
  const [keep, action] = allElements(dialog).filter(node => node.tagName === "BUTTON");
  const asked = { message: textOf(allElements(dialog).find(node => node.tagName === "P")), confirmLabel: textOf(action) };
  await dom.click(accept ? action : keep);
  for (let i = 0; i < 3; i++) await dom.flush();
  return asked;
}

// The open confirm dialog's tone: "danger" for actions that lose data, else "primary".
async function confirmTone(dom) {
  for (let i = 0; i < 5 && !confirmDialogIn(dom); i++) await dom.flush();
  const action = allElements(confirmDialogIn(dom)).filter(node => node.tagName === "BUTTON")[1];
  return /ui-button--danger/.test(action.getAttribute("class")) ? "danger" : "primary";
}

// Presses a dialog's overlay the way a click lands: pointer down, then the click. A
// `startedOn` node is where the pointer went down, as when a text selection is dragged out.
async function pressOverlay(dom, overlay, startedOn = overlay) {
  await dom.pointer(overlay, "onPointerDown", { target: startedOn });
  await dom.click(overlay);
}

// Types into a field the way React delivers it: the field's onChange, then each ancestor's
// as the change bubbles up (Second Brain's dialogs notice a change on their panel).
async function typeBubbling(node, value) {
  await React.act(async () => {
    node.value = value;
    for (let current = node; current; current = current.parentNode) {
      const key = Object.keys(current).find(candidate => candidate.startsWith("__reactProps$"));
      if (key) current[key].onChange?.({ target: node, currentTarget: current });
    }
  });
}

// Answers the "Discard?" question a changed dialog asks on Escape and returns what it showed.
async function answerDiscard(dom, discard) {
  for (let i = 0; i < 5 && !confirmDialogIn(dom); i++) await dom.flush();
  const dialog = confirmDialogIn(dom);
  assert.ok(dialog, "Escape asks before discarding");
  const buttons = allElements(dialog).filter(node => node.tagName === "BUTTON");
  const shown = { message: textOf(allElements(dialog).find(node => node.tagName === "P")), buttons: buttons.map(textOf), focused: document.activeElement === buttons[0] };
  await dom.click(discard ? buttons[1] : buttons[0]);
  for (let i = 0; i < 3; i++) await dom.flush();
  return shown;
}

const modalPanel = dom => allElements(dom.container).find(node => node.getAttribute?.("role") === "dialog" && node.getAttribute("aria-modal") === "true" && !node.getAttribute("data-testid"));

function threadGroupSection(dom, label) {
  return allElements(dom.container).find(node => node.tagName === "SECTION" && node.getAttribute?.("aria-label") === `${label} threads`);
}

// The chevron opens and closes a group; activating the group's name selects its threads.
function threadGroupToggle(dom, label) {
  return allElements(threadGroupSection(dom, label)).find(node => node.tagName === "BUTTON" && /^(Show|Hide) /.test(node.getAttribute?.("aria-label") || ""));
}

async function openThreadGroup(dom, label) {
  const toggle = threadGroupToggle(dom, label);
  if (toggle.getAttribute("aria-expanded") !== "true") await dom.click(toggle);
}

