test("Rem tools merge the shared library with thread selections and add new entries to it", async () => {
  const { default: RemResources } = await viteServer.ssrLoadModule("/src/components/RemResources.jsx");
  let library = {
    skillsDir: "/data/skills",
    skills: [{ path: "/data/skills/release-notes", name: "release-notes", description: "Write release notes", origin: "codex", available: true, registered: false }],
    mcpServers: [{ name: "github", type: "stdio", url: "", command: "npx", args: ["-y", "gh"], env: ["GH_HOST"], description: "GitHub issues", addedBy: "cli" }],
  };
  const posts = [];
  const fetchMock = createFetchMock([(url, options = {}) => {
    if (url !== "/api/rem-resources") return null;
    if (options.method === "POST") {
      const body = JSON.parse(options.body);
      posts.push(body);
      if (body.action === "save_mcp") library = { ...library, mcpServers: [...library.mcpServers.filter((server) => server.name !== body.replace), { ...body.server, addedBy: "app" }] };
    }
    return { ok: true, status: 200, json: async () => library };
  }]);
  let saved;
  function Editor() {
    const [value, setValue] = React.useState({ shell: true, web: false, skills: [{ path: "/legacy/notes", enabled: true }], mcpServers: [] });
    return React.createElement(RemResources, { value, onChange: (next) => { saved = next; setValue(next); } });
  }
  const dom = await mountReact(React.createElement(Editor), fetchMock);
  try {
    await dom.flush();
    assert.match(dom.text(), /Write release notes/);
    assert.match(dom.text(), /GitHub issues/);
    const skillBadge = () => textOf(allElements(dom.ancestor(dom.byLabel("release-notes"), "LI")).find((el) => el.getAttribute?.("class") === "rem-tools__badge"));
    assert.equal(reactProps(dom.byLabel("release-notes")).checked, false, "library entries start off");
    assert.equal(skillBadge(), "Codex", "an off skill shows the folder it came from");
    assert.equal(reactProps(dom.byLabel("github")).checked, false);
    assert.equal(reactProps(dom.byLabel("notes")).checked, true, "thread-only entries stay visible");
    await dom.change(dom.byLabel("release-notes"), true);
    assert.equal(skillBadge(), "Rem", "an enabled skill belongs to Rem for every provider");
    await dom.change(dom.byLabel("release-notes"), false);
    assert.equal(skillBadge(), "Codex");
    await dom.change(dom.byLabel("release-notes"), true);
    await dom.change(dom.byLabel("github"), true);
    assert.deepEqual(saved.skills, [{ path: "/legacy/notes", enabled: true }, { path: "/data/skills/release-notes", enabled: true }]);
    assert.deepEqual(saved.mcpServers, [{ name: "github", type: "stdio", url: "", command: "npx", args: ["-y", "gh"], enabled: true, library: true }]);
    await dom.change(dom.byLabel("github"), false);
    assert.deepEqual(saved.mcpServers, []);
    await dom.click(dom.byLabel("Remove skill notes"));
    assert.deepEqual(saved.skills, [{ path: "/data/skills/release-notes", enabled: true }]);
    await dom.click(dom.byLabel("Add MCP server"));
    await dom.change(dom.byLabel("Server name"), "docs");
    const urlField = dom.byLabel("Server URL");
    await dom.focus(urlField);
    await dom.change(urlField, "https://old.example/mcp");
    await dom.change(urlField, "");
    assert.equal(urlField.value, "");
    await dom.change(urlField, "https://example.com/mcp");
    await dom.blur(urlField);
    await dom.pointer(dom.ancestor(urlField, "FORM"), "onSubmit");
    await dom.flush();
    assert.deepEqual(posts.at(-1), { action: "save_mcp", server: { name: "docs", type: "http", url: "https://example.com/mcp", description: "" } });
    assert.deepEqual(saved.mcpServers, [{ name: "docs", type: "http", url: "https://example.com/mcp", command: "", args: [], enabled: true, library: true }]);
    assert.equal(reactProps(dom.byLabel("docs")).checked, true, "a server added here is on for this selection");
    assert.throws(() => dom.byLabel("Server URL"), "the form closes after saving");

    // A local server names the environment variables mcp-tool steps pass to it. The
    // names go to the library; a thread's selection never carries them.
    await dom.click(dom.byLabel("Edit server github"));
    const envField = dom.byLabel("Server environment variables");
    assert.equal(envField.value, "GH_HOST");
    await dom.focus(envField);
    await dom.change(envField, "");
    assert.equal(envField.value, "");
    await dom.change(envField, "GH_HOST\nGITHUB_PERSONAL_ACCESS_TOKEN, GH_HOST");
    await dom.blur(envField);
    await dom.pointer(dom.ancestor(envField, "FORM"), "onSubmit");
    await dom.flush();
    assert.deepEqual(posts.at(-1), {
      action: "save_mcp",
      replace: "github",
      server: { name: "github", type: "stdio", command: "npx", args: ["-y", "gh"], env: ["GH_HOST", "GITHUB_PERSONAL_ACCESS_TOKEN"], description: "GitHub issues" },
    });
    await dom.change(dom.byLabel("github"), true);
    assert.ok(saved.mcpServers.every((server) => !("env" in server)), "thread selections carry no environment names");
  } finally { await dom.unmount(); }
});

test("Rem tools clear a local server's package cache and say how much it freed", async () => {
  const { default: RemResources, cacheSizeText } = await viteServer.ssrLoadModule("/src/components/RemResources.jsx");
  assert.equal(cacheSizeText(512), "512 bytes");
  assert.equal(cacheSizeText(12_345_678), "12.3 MB");
  assert.equal(cacheSizeText(2_500_000_000), "2.5 GB");
  const library = {
    skillsDir: "/data/skills",
    skills: [],
    mcpServers: [
      { name: "github", type: "stdio", url: "", command: "npx", args: ["-y", "gh@1.0.0"], env: [], description: "", addedBy: "cli" },
      { name: "docs", type: "http", url: "https://example.com/mcp", command: "", args: [], env: [], description: "", addedBy: "cli" },
    ],
  };
  const posts = [];
  let freed = 12_345_678;
  const fetchMock = createFetchMock([(url, options = {}) => {
    if (url !== "/api/rem-resources") return null;
    if (options.method !== "POST") return { ok: true, status: 200, json: async () => library };
    const body = JSON.parse(options.body);
    posts.push(body);
    const payload = { ...library, cacheCleared: freed };
    freed = 0;
    return { ok: true, status: 200, json: async () => payload };
  }]);
  const value = { shell: true, web: false, skills: [], mcpServers: [] };
  const dom = await mountReact(React.createElement(RemResources, { value, onChange: () => {} }), fetchMock);
  try {
    await dom.flush();
    assert.throws(() => dom.byLabel("Clear package cache for docs"), "an HTTP server has no package cache");
    await dom.click(dom.byLabel("Clear package cache for github"));
    await dom.flush();
    assert.deepEqual(posts, [{ action: "clear_mcp_cache", name: "github" }]);
    assert.match(dom.text(), /Cleared 12\.3 MB from github's package cache\. Its next start in a workflow downloads its packages again\./);
    await dom.click(dom.byLabel("Clear package cache for github"));
    await dom.flush();
    assert.match(dom.text(), /github's package cache is already empty\./);
  } finally { await dom.unmount(); }
});

test("Rem tools list Second Brains on by default only while Settings > Memory enables them", async () => {
  const { default: RemResources } = await viteServer.ssrLoadModule("/src/components/RemResources.jsx");
  const { resetSecondBrainStore } = await viteServer.ssrLoadModule("/src/lib/secondBrainStore.js");
  const brain = (id, settings = { allowCloud: true }) => ({ id, name: id, root: `/brains/${id}`, state: "available", settings });
  const fetchMock = createFetchMock([
    jsonResponse("/api/rem-resources", { skills: [], mcpServers: [] }),
    jsonResponse("/api/second-brains", { result: { brains: [brain("school"), brain("work"), brain("private", { allowCloud: false })] } }),
  ]);
  let saved;
  function Editor({ memory }) {
    const [value, setValue] = React.useState({ shell: true, web: true, skills: [], mcpServers: [] });
    return React.createElement(RemResources, { value, memory, onChange: (next) => { saved = next; setValue(next); } });
  }
  resetSecondBrainStore();
  const dom = await mountReact(React.createElement(Editor, { memory: { secondBrainEnabled: true, secondBrainRoot: "/brains/school" } }), fetchMock);
  try {
    for (let attempt = 0; attempt < 60 && !/Second Brains/.test(dom.text()); attempt++) {
      await React.act(async () => { await new Promise((resolve) => setTimeout(resolve, 50)); });
    }
    assert.match(dom.text(), /2 on/);
    assert.equal(reactProps(dom.byLabel("school")).checked, true, "a thread without a brain choice has every brain on");
    assert.equal(reactProps(dom.byLabel("work")).checked, true);
    assert.equal(reactProps(dom.byLabel("private")).checked, false, "brains without cloud permission cannot be used");
    assert.equal(reactProps(dom.byLabel("private")).disabled, true);
    await dom.change(dom.byLabel("work"), false);
    assert.deepEqual(saved.disabledSecondBrains, ["work"]);
    assert.equal(saved.secondBrains, undefined);
    assert.match(dom.text(), /1 on/);
    await dom.change(dom.byLabel("work"), true);
    assert.deepEqual(saved.disabledSecondBrains, []);
  } finally { await dom.unmount(); }
  // A Memory folder without cloud permission is reached by path, which cannot join registered brains.
  const mixed = await mountReact(React.createElement(Editor, { memory: { secondBrainEnabled: true, secondBrainRoot: "/brains/private" } }), fetchMock);
  try {
    await mixed.flush();
    assert.equal(reactProps(mixed.byLabel("private")).checked, true);
    assert.match(mixed.text(), /Skipped while other brains are on/);
    assert.match(mixed.text(), /2 on/, "the summary counts only the brains Rem receives");
  } finally { await mixed.unmount(); }
  // The library is loaded now, so only the setting can hide the section.
  const off = await mountReact(React.createElement(Editor, { memory: { secondBrainEnabled: false, secondBrainRoot: "" } }), fetchMock);
  try {
    await off.flush();
    assert.match(off.text(), /Built-in/);
    assert.doesNotMatch(off.text(), /Second Brains/);
  } finally { await off.unmount(); resetSecondBrainStore(); }
});

test("Second Brain version dialogs load a document's stored versions when they open", async () => {
  const { default: SecondBrainDialogs } = await viteServer.ssrLoadModule("/src/components/SecondBrainDialogs.jsx");
  const store = await viteServer.ssrLoadModule("/src/lib/secondBrainStore.js");
  const brain = { id: "brain-1", name: "Notes", root: "/notes", state: "available", settings: {}, index: {} };
  const doc = { id: "doc-1", brainId: brain.id, title: "Plan", path: "plan.md", type: "markdown", version: "v2", dates: { modified: "2026-11-20T00:00:00Z" }, passageCount: 1, versionCount: 1, historySize: 60 };
  const snapshot = { brains: [brain], activeBrainId: brain.id, documents: [doc], collections: [], savedSearches: [], reports: [], citations: [], jobs: [], projects: [], topics: [], health: [], families: [], tasks: [], views: {}, revision: "1.a.1" };
  const history = createDeferred();
  const asked = [];
  const fetchMock = createFetchMock([
    jsonResponse("/api/second-brains", { result: snapshot }),
    (url, options = {}) => {
      if (url !== "/api/second-brains" || options.method !== "POST") return null;
      const { action, params } = JSON.parse(options.body);
      if (action !== "passages") return null;
      asked.push(params);
      const result = { documents: [{ id: doc.id, brainId: brain.id, version: "v2", blocks: [{ id: "b1", heading: "Plan", text: "Ship on Friday." }] }], missing: [] };
      if (!params.history) return { ok: true, status: 200, json: async () => ({ result }) };
      return { ok: true, status: 200, json: async () => { await history.promise; return { result: { ...result, documents: [{ ...result.documents[0], versions: [{ hash: "v1", at: "2026-11-01T00:00:00Z", note: "First draft", blocks: { b1: "Ship on Monday." } }] }] } }; } };
    },
  ]);
  store.resetSecondBrainStore();
  const dom = await mountReact(React.createElement(SecondBrainDialogs, { provider: { id: "codex", name: "Codex", model: "cli-default" } }), fetchMock);
  try {
    await React.act(async () => { await store.refreshLibrary({ initial: true }); });
    assert.deepEqual(asked, [{ ids: ["doc-1"] }], "the snapshot's passages come in one batch, without history");
    // The reader's Compare with current.
    await React.act(async () => { store.openDialog("version-diff", { docId: doc.id, from: "v1" }); });
    assert.match(dom.text(), /Loading older versions/);
    await React.act(async () => { history.resolve(); });
    await dom.flush(10);
    assert.deepEqual(asked.at(-1), { ids: ["doc-1"], history: true });
    assert.match(dom.text(), /Version v1/);
    assert.match(dom.text(), /Ship on Monday\./);
    assert.match(dom.text(), /Ship on Friday\./);
    // A report's changed citation opens the same dialog; the versions are already here.
    await React.act(async () => { store.closeDialog(); });
    const citation = { id: "cit-1", docId: doc.id, blockId: "b1", quote: "Ship on Monday", version: "v1", state: "changed" };
    await React.act(async () => { store.openDialog("version-diff", { docId: doc.id, from: "v1", blockId: "b1", citation, reportId: "report-1" }); });
    assert.doesNotMatch(dom.text(), /Loading older versions/);
    assert.match(dom.text(), /no longer appears/);
    assert.equal(asked.length, 2, "the stored versions were fetched once");
  } finally { await dom.unmount(); store.resetSecondBrainStore(); }
});

test("Second Brain dialogs stay open on a press outside once a field changes, and Escape asks first", async () => {
  const { default: SecondBrainDialogs } = await viteServer.ssrLoadModule("/src/components/SecondBrainDialogs.jsx");
  const store = await viteServer.ssrLoadModule("/src/lib/secondBrainStore.js");
  const brain = { id: "brain-1", name: "Notes", root: "/notes", state: "available", settings: {}, index: {} };
  const snapshot = { brains: [brain], activeBrainId: brain.id, documents: [], collections: [], savedSearches: [], reports: [], citations: [], jobs: [], projects: [], topics: [], health: [], families: [], tasks: [], views: {}, revision: "1.a.1" };
  const fetchMock = createFetchMock([jsonResponse("/api/second-brains", { result: snapshot })]);
  store.resetSecondBrainStore();
  const dom = await mountReact(React.createElement(SecondBrainDialogs, { provider: { id: "codex", name: "Codex", model: "cli-default" } }), fetchMock);
  const open = () => /Captured sources wait in Inbox/.test(dom.text());
  try {
    await React.act(async () => { await store.refreshLibrary({ initial: true }); });
    await React.act(async () => { store.openDialog("capture"); });
    assert.ok(open());
    await pressOverlay(dom, modalPanel(dom).parentNode);
    assert.ok(!open(), "an untouched dialog closes on a press outside");

    await React.act(async () => { store.openDialog("capture"); });
    await typeBubbling(dom.controlAfterLabel("Page address"), "https://example.com/notes");
    await pressOverlay(dom, modalPanel(dom).parentNode, dom.controlAfterLabel("Page address"));
    await pressOverlay(dom, modalPanel(dom).parentNode);
    assert.ok(open(), "a press outside keeps the typed address");
    assert.equal(dom.controlAfterLabel("Page address").value, "https://example.com/notes");

    await dom.keyDown(modalPanel(dom), "Escape");
    assert.deepEqual(await answerDiscard(dom, false), { message: "Discard what you entered in this dialog?", buttons: ["Keep editing", "Discard"], focused: true });
    assert.ok(open());
    assert.equal(dom.controlAfterLabel("Page address").value, "https://example.com/notes");
    await dom.keyDown(modalPanel(dom), "Escape");
    await answerDiscard(dom, true);
    assert.ok(!open(), "Discard closes it");
  } finally { await dom.unmount(); store.resetSecondBrainStore(); }
});

test("Second Brain Delete collection offers Undo on a notice that stays at least 10 seconds", async () => {
  const { default: SecondBrainWorkspace } = await viteServer.ssrLoadModule("/src/components/SecondBrainWorkspace.jsx");
  const store = await viteServer.ssrLoadModule("/src/lib/secondBrainStore.js");
  const brain = { id: "brain-1", name: "Notes", root: "/notes", state: "available", settings: {}, index: { state: "ready" } };
  const collection = { id: "col-1", brainId: brain.id, name: "Reading list", brief: "What to read", updated: "2026-11-20T00:00:00Z", sections: [{ id: "sec-1", title: "Evidence", items: [] }], questions: [] };
  // The library service: mutate writes go to this copy and later snapshots return it.
  const server = { brains: [brain], activeBrainId: brain.id, documents: [], collections: [collection], savedSearches: [], reports: [], citations: [], jobs: [], projects: [], topics: [], health: [], families: [], tasks: [], views: {}, revision: "1" };
  const mutations = [];
  const fetchMock = createFetchMock([
    (url, options = {}) => {
      if (!url.startsWith("/api/second-brains")) return null;
      let result = structuredClone(server);
      if (options.method === "POST") {
        const { action, params } = JSON.parse(options.body);
        result = {};
        if (action === "mutate") {
          mutations.push(params);
          const rest = server[params.kind].filter(item => item.id !== params.id);
          server[params.kind] = params.delete ? rest : [...rest, params.item];
          server.revision = String(Number(server.revision) + 1);
        }
      }
      return { ok: true, status: 200, json: async () => ({ result }) };
    },
  ]);
  store.resetSecondBrainStore();
  const dom = await mountReact(React.createElement(SecondBrainWorkspace, { onClose() {} }), fetchMock);
  try {
    for (let attempt = 0; attempt < 60 && !store.getState().loaded; attempt++) await dom.flush();
    await React.act(async () => { store.navigate("collections", { collectionId: collection.id }); });
    await dom.click(dom.byLabel("More collection actions"));
    await dom.click(dom.ancestor(dom.byExactText("Delete collection"), "BUTTON"));
    await React.act(async () => { await store.flushLibraryWrites(); });
    assert.deepEqual(mutations.at(-1), { kind: "collections", id: collection.id, delete: true });
    assert.match(dom.text(), /Deleted collection “Reading list”\./);
    assert.match(dom.text(), /All collections|No collections yet/, "the page went back to the list");
    // Every timer up to 9.999 seconds runs: the notice and its Undo button are still there.
    await dom.flush(9999);
    assert.match(dom.text(), /Deleted collection “Reading list”\./);
    const toast = dom.ancestor(dom.byExactText("Undo"), node => node.getAttribute?.("class") === "sb-toast");
    // While the pointer is on it, even the 10-second timer doesn't close it.
    await dom.pointer(toast, "onMouseEnter");
    await dom.flush(60000);
    assert.match(dom.text(), /Deleted collection “Reading list”\./);
    await dom.pointer(toast, "onMouseLeave");
    await dom.click(dom.ancestor(dom.byExactText("Undo"), "BUTTON"));
    await React.act(async () => { await store.flushLibraryWrites(); });
    assert.doesNotMatch(dom.text(), /Deleted collection/);
    assert.deepEqual(mutations.at(-1), { kind: "collections", id: collection.id, item: collection });
    assert.deepEqual(store.getState().collections, [collection]);
    assert.equal(store.viewFor(store.getState()).collectionId, "", "Undo restores without opening the collection again");
    // A notice left alone closes after its 10 seconds.
    await React.act(async () => { store.deleteCollection(collection.id); });
    await dom.flush(10000);
    assert.doesNotMatch(dom.text(), /Deleted collection/);
  } finally { await dom.unmount(); store.resetSecondBrainStore(); }
});

test("Second Brain's Index needs attention warning opens the error and offers Rebuild index", async () => {
  const { default: SecondBrainWorkspace } = await viteServer.ssrLoadModule("/src/components/SecondBrainWorkspace.jsx");
  const store = await viteServer.ssrLoadModule("/src/lib/secondBrainStore.js");
  const settings = { metadata: "portable", semantic: false, embeddings: "local", allowCloud: true, formats: { markdown: true, html: true, text: true, pdf: false, ocr: false }, ocrLanguage: "eng", obsidian: false, folderRules: {} };
  const brain = { id: "brain-1", name: "Notes", root: "/notes", state: "available", settings, index: { state: "failed", error: "disk full", documents: 3, passages: 9, generation: 2, asOf: "2026-11-20T00:00:00Z" } };
  const snapshot = { brains: [brain], activeBrainId: brain.id, documents: [], collections: [], savedSearches: [], reports: [], citations: [], jobs: [], projects: [], topics: [], health: [], families: [], tasks: [], views: {}, revision: "1" };
  const started = [];
  const fetchMock = createFetchMock([
    (url, options = {}) => {
      if (!url.startsWith("/api/second-brains")) return null;
      let result = structuredClone(snapshot);
      if (options.method === "POST") {
        const { action, params } = JSON.parse(options.body);
        result = {};
        if (action === "task") {
          started.push(params);
          result = { id: `task-${started.length}`, brainId: params.brainId, kind: params.kind, label: params.label, steps: params.steps, step: 0, progress: 0, state: "running" };
        }
      }
      return { ok: true, status: 200, json: async () => ({ result }) };
    },
  ]);
  store.resetSecondBrainStore();
  const dom = await mountReact(React.createElement(SecondBrainWorkspace, { onClose() {} }), fetchMock);
  const warning = () => dom.byLabel("Index needs attention");
  const panel = () => allElements(dom.container).find(node => node.getAttribute?.("role") === "dialog" && node.getAttribute("aria-label") === "Index needs attention");
  const panelButton = text => allElements(panel()).find(node => node.tagName === "BUTTON" && textOf(node) === text);
  try {
    for (let attempt = 0; attempt < 60 && !store.getState().loaded; attempt++) await dom.flush();
    assert.equal(warning().tagName, "BUTTON", "the warning is a button, not a plain label");
    assert.doesNotMatch(dom.text(), /disk full/, "the error stays hidden until the warning is opened");
    await dom.focus(warning());
    await dom.click(warning());
    assert.equal(warning().getAttribute("aria-expanded"), "true");
    assert.ok(panel(), "the warning opens its panel");
    assert.equal(document.activeElement, panel(), "the panel takes focus when it opens");
    assert.match(textOf(panel()), /Indexing stopped with an error/);
    assert.equal(textOf(dom.ancestor(dom.byExactText("disk full"), "PRE")), "disk full", "the stored error is visible text");
    assert.ok(panelButton("Rebuild index"));
    assert.ok(panelButton("Library health"));
    // Escape closes the panel and puts focus back on the warning.
    await dom.dispatchWindow("keydown", { key: "Escape" });
    assert.equal(panel(), undefined);
    assert.equal(document.activeElement, warning(), "Escape returns focus to the warning button");
    // Rebuild index starts the same index task as the button in Brain settings.
    await dom.click(warning());
    await dom.click(panelButton("Rebuild index"));
    await dom.flush();
    assert.equal(started.length, 1);
    assert.deepEqual(started[0], { kind: "index", label: "Rebuilding the Notes index", brainId: brain.id, steps: ["Scanning folder", "Extracting text", "Building passages", "Publishing generation"], provider: started[0].provider });
    assert.equal(panel(), undefined, "starting the rebuild closes the panel");
    await React.act(async () => { store.navigate("settings"); });
    await dom.click(dom.ancestor(dom.byExactText("Rebuild index"), "BUTTON"));
    await dom.flush();
    assert.equal(started.length, 2);
    assert.deepEqual(started[1], started[0], "both buttons send the same request");
    // Library health opens that page.
    await dom.click(warning());
    await dom.click(panelButton("Library health"));
    assert.equal(store.viewFor(store.getState()).section, "health");
    assert.equal(panel(), undefined);
  } finally { await dom.unmount(); store.resetSecondBrainStore(); }
});

