test("Rem commit jobs survive leaving the explorer and restore branch-specific drafts", async () => {
  const jobs = {};
  let branch = "main", count = 0;
  const workspace = { trustProjectRoot: async () => {}, listDirectory: async () => ({ entries: [] }),
    gitStatus: async () => ({ active: true, branch, branches: ["main", "feature"], entries: [{ path: "note", status: "M", staged: true }] }),
    gitHistory: async () => ({ active: true, commits: [] }), gitWorktrees: async () => ({ active: true, worktrees: [] }) };
  const fetchMock = createFetchMock([url => url.startsWith("/api/generation-jobs?") ? { ok: true, json: async () => ({ jobs: jobs[new URLSearchParams(url.split("?")[1]).get("branch")] ? [jobs[new URLSearchParams(url.split("?")[1]).get("branch")]] : [] }) } : null]);
  const mount = () => mountReact(React.createElement(codeFileExplorerModule.default, { workflow: { projectRoot: "/repo" } }), fetchMock, { desktop: { workspace } });
  let dom = await mount();
  const start = async () => {
    window.dispatchEvent = event => {
      if (event.type === "gofer:rem-commit-message") {
        assert.equal(event.detail.background, true);
        assert.equal(event.detail.branch, branch);
        event.detail.handled = true;
        jobs[branch] = { id: String(++count), status: "running", branch };
        event.detail.resolve(jobs[branch]);
      }
    };
    await dom.click(dom.byLabel("Source control")); await showSourceChanges(dom); await dom.flush();
    await dom.click(dom.byLabel("Generate commit message with Rem")); await dom.flush();
  };
  try {
    await start();
    await dom.unmount(); branch = "feature"; dom = await mount();
    await start();
    assert.equal(jobs.main.status, "running");
    assert.equal(jobs.feature.status, "running");
    await dom.unmount();
    jobs.main = { ...jobs.main, status: "completed", result: { message: "fix: main result" } };
    jobs.feature = { ...jobs.feature, status: "completed", result: { message: "fix: feature result" } };
    branch = "main"; dom = await mount();
    await dom.click(dom.byLabel("Source control")); await showSourceChanges(dom); await dom.flush();
    assert.equal(reactProps(dom.byLabel("Commit message")).value, "fix: main result");
    await dom.unmount(); branch = "feature"; dom = await mount();
    await dom.click(dom.byLabel("Source control")); await showSourceChanges(dom); await dom.flush();
    assert.equal(reactProps(dom.byLabel("Commit message")).value, "fix: feature result");
  } finally { await dom.unmount(); }
});

test("Rem accepts staged diffs larger than 200000 characters", async () => {
  const { gitRepositoryAction } = require("../../electron/git-status.cjs");
  const diff = Array.from({ length: 92 }, (_, i) => `diff --git a/file-${i} b/file-${i}\n${"+change\n".repeat(1000)}`).join("");
  const result = await gitRepositoryAction("/repo", "staged-diff", "", { runGit: async args => {
    if (args.includes("rev-parse")) return "/repo\n";
    if (args.includes("--diff-filter=U")) return "";
    if (args.includes("write-tree")) return "staged-tree\n";
    if (args.includes("--cached")) return diff;
    throw new Error(`Unexpected Git command: ${args}`);
  } });
  assert.equal(result.diff, undefined);
  assert.equal(result.inspectStaged, true);
  assert.equal(result.tree, "staged-tree");
});


test("Run on lists paired computers, sends the choice, and locks once a thread starts", async () => {
  const machines = [{ id: "11111111-1111-4111-8111-111111111111", name: "Studio desktop" }];
  function Harness({ locked = false }) {
    const [machine, setMachine] = React.useState("");
    return React.createElement(chatComposerModule.default, {
      draft: "hello", provider: "codex", machines, machine, machineLocked: locked,
      onMachineChange: setMachine, onDraftChange() {}, onSend() {},
    });
  }
  const dom = await mountReact(React.createElement(Harness), createFetchMock([]));
  const select = dom.byLabel("Run on");
  assert.equal(reactProps(select).value, "");
  await dom.change(select, machines[0].id);
  assert.equal(reactProps(dom.byLabel("Run on")).value, machines[0].id);
  assert.equal(chatThreadsModule.chatStreamRequestBody({ provider: "codex", machine: reactProps(select).value }).machine, machines[0].id);
  assert.equal("machine" in chatThreadsModule.chatStreamRequestBody({ provider: "codex" }), false);
  // Claude Code threads name their account; other providers and remote desktops never do.
  assert.equal(chatThreadsModule.chatStreamRequestBody({ provider: "claude_code", claudeAccount: "work" }).providerProfile, "work");
  assert.equal("providerProfile" in chatThreadsModule.chatStreamRequestBody({ provider: "codex", claudeAccount: "work" }), false);
  assert.equal("providerProfile" in chatThreadsModule.chatStreamRequestBody({ provider: "claude_code", claudeAccount: "work", machine: machines[0].id }), false);
  // Every provider with accounts names its own account from Settings > Rem.
  const providerAccounts = { claude_code: "work", codex: "auto" };
  assert.equal(chatThreadsModule.chatStreamRequestBody({ provider: "codex", providerAccounts }).providerProfile, "auto");
  assert.equal(chatThreadsModule.chatStreamRequestBody({ provider: "claude_code", providerAccounts }).providerProfile, "work");
  assert.equal("providerProfile" in chatThreadsModule.chatStreamRequestBody({ provider: "grok", providerAccounts }), false);
  assert.equal("providerProfile" in chatThreadsModule.chatStreamRequestBody({ provider: "codex", providerAccounts, machine: machines[0].id }), false);
  // The thread's own account wins over Rem's setting, including the default sign-in.
  assert.equal(chatThreadsModule.chatStreamRequestBody({ provider: "codex", providerAccounts, threadAccount: "home" }).providerProfile, "home");
  assert.equal(chatThreadsModule.chatStreamRequestBody({ provider: "claude_code", providerAccounts, threadAccount: "@default" }).providerProfile, "@default");
  assert.equal(chatThreadsModule.chatStreamRequestBody({ provider: "grok", threadAccount: "spare" }).providerProfile, "spare");
  assert.equal("providerProfile" in chatThreadsModule.chatStreamRequestBody({ provider: "codex", threadAccount: "home", machine: machines[0].id }), false);
  await dom.unmount();
  const locked = await mountReact(React.createElement(Harness, { locked: true }), createFetchMock([]));
  assert.equal(reactProps(locked.byLabel("Run on")).disabled, true);
  await locked.unmount();
  // Without paired computers the composer shows no machine menu.
  const alone = await mountReact(React.createElement(chatComposerModule.default, { draft: "", provider: "codex", onDraftChange() {}, onSend() {} }), createFetchMock([]));
  assert.equal(allElements(alone.container).some(node => node.getAttribute?.("aria-label") === "Run on"), false);
  await alone.unmount();
});

