function workflowDocumentWriteHarness(request) {
  const source = fs.readFileSync(path.join(frontendRoot, 'src/pages/App.jsx'), 'utf8');
  const block = source.slice(source.indexOf('  function queueWorkflowDocumentWrite('), source.indexOf('  function updateRattishGraphMetadata('));
  const sessions = new Map();
  const accepted = [];
  const analyses = [];
  function documentSession(id) {
    if (!sessions.has(id)) {
      const state = { current: null };
      sessions.set(id, { documentWritesRef: { current: Promise.resolve() }, rattishEditorStateRef: state, graphHistoryRef: { current: graphEditHistoryModule.EMPTY_GRAPH_HISTORY },
        rattishAnalysisTimerRef: { current: null }, rattishAnalysisRequestRef: { current: 0 }, rattishMetadataPendingRef: { current: false }, rattishMetadataSavingRef: { current: null },
        setRattishEditorState(next) { state.current = next; } });
    }
    return sessions.get(id);
  }
  const notices = [];
  const functions = vm.runInNewContext(`(function () { ${block}; return { saveWorkflowDocument, mutateActiveRattish, stepGraphHistory }; })()`, {
    documentSession, fetch: request, apiUrl: value => value, window: { clearTimeout },
    ...graphEditHistoryModule, graphHistoryChanged() {},
    scheduleRattishAnalysis: (...args) => analyses.push(args),
    rattishEditorRef: { current: { acceptDocument: (...args) => accepted.push(args) } },
    setTopBarNotice: notice => notices.push(notice), loadWorkflows: async () => {}, saveRattishMetadataNow: async () => true,
  });
  return { ...functions, documentSession, accepted, analyses, notices };
}

function deferredDocumentResponse() {
  let resolve;
  const promise = new Promise(done => { resolve = done; });
  return { promise, resolve: document => resolve({ ok: true, json: async () => ({ document }) }) };
}

const writeTestWorkflow = id => ({ id, sourceFormat: 'rattish', sourcePath: `/projects/${id}/workflow.rattish` });
const writeTestDocument = (source, savedRevision = 'r1', dirty = false) => ({ source, savedRevision, dirty, runnable: true });

test('toolbar Stop explains overlapping runs instead of silently disabling itself', () => {
  const run = (runId) => ({ workflowId: 'demo', runId, status: 'running' });
  assert.deepEqual(appModule.workflowStopControl([]), { stopDisabled: true, stopTitle: 'No run in progress' });
  assert.deepEqual(appModule.workflowStopControl([run('a')]), { stopDisabled: false, stopTitle: 'Stop this run' });
  const several = appModule.workflowStopControl([run('a'), run('b')]);
  assert.equal(several.stopDisabled, false);
  assert.match(several.stopTitle, /2 runs in progress/);
});

test('a clean Rattish editor follows a file changed on disk before running', async () => {
  const state = { current: { document: writeTestDocument('old', 'r1') } };
  const session = { rattishEditorStateRef: state, setRattishEditorState(next) { state.current = next; } };
  const followed = await appModule.followSavedRattishDocument(session, async () => writeTestDocument('edited by Rem', 'r2'));
  assert.equal(followed.savedRevision, 'r2');
  assert.equal(state.current.document.source, 'edited by Rem');

  state.current = { document: writeTestDocument('unsaved edit', 'r1', true) };
  let loads = 0;
  const kept = await appModule.followSavedRattishDocument(session, async () => { loads += 1; return writeTestDocument('disk', 'r3'); });
  assert.equal(loads, 0);
  assert.equal(kept.source, 'unsaved edit');

  const missing = { rattishEditorStateRef: { current: null }, setRattishEditorState(next) { this.rattishEditorStateRef.current = next; } };
  assert.equal((await appModule.followSavedRattishDocument(missing, async () => writeTestDocument('disk', 'r4'))).savedRevision, 'r4');
});

test('workflow source typed during save retains its draft and advances the saved revision', async () => {
  const pending = deferredDocumentResponse();
  const harness = workflowDocumentWriteHarness(() => pending.promise);
  const target = writeTestWorkflow('alpha');
  const session = harness.documentSession(target.id);
  session.setRattishEditorState({ document: writeTestDocument('submitted', 'r1', true) });
  const saving = harness.saveWorkflowDocument(target);
  await Promise.resolve(); await Promise.resolve();
  session.setRattishEditorState({ document: writeTestDocument('newer draft', 'r1', true) });
  pending.resolve(writeTestDocument('submitted', 'r2'));
  await assert.rejects(saving, /changed during save/);
  assert.equal(session.rattishEditorStateRef.current.document.source, 'newer draft');
  assert.equal(session.rattishEditorStateRef.current.document.savedRevision, 'r2');
  assert.equal(session.rattishEditorStateRef.current.document.savedSource, 'submitted');
  assert.equal(session.rattishEditorStateRef.current.document.dirty, true);
  assert.equal(harness.accepted.length, 0, 'new source buffer was reset');
  assert.deepEqual(harness.analyses, [['newer draft', target.sourcePath]]);
});

test('workflow graph mutation cannot overwrite source typed while its request is pending', async () => {
  const pending = deferredDocumentResponse();
  let started;
  const requested = new Promise(resolve => { started = resolve; });
  const harness = workflowDocumentWriteHarness(() => { started(); return pending.promise; });
  const target = writeTestWorkflow('alpha');
  const session = harness.documentSession(target.id);
  session.setRattishEditorState({ document: writeTestDocument('disk') });
  const mutation = harness.mutateActiveRattish([{ kind: 'edit-node' }], target);
  await requested;
  session.setRattishEditorState({ document: writeTestDocument('newer source', 'r1', true) });
  pending.resolve(writeTestDocument('graph edit', 'r2'));
  assert.equal((await mutation).error, 'Graph changes were saved. Your newer source edits are still unsaved.');
  assert.equal(session.rattishEditorStateRef.current.document.source, 'newer source');
  assert.equal(session.rattishEditorStateRef.current.document.savedRevision, 'r2');
  assert.equal(session.rattishEditorStateRef.current.document.dirty, true);
  assert.equal(harness.accepted.length, 0);
});

test('workflow document writes serialize per workflow and run independently across workflows', async () => {
  const calls = [];
  const pending = [];
  const harness = workflowDocumentWriteHarness((url, init) => {
    calls.push({ url, body: JSON.parse(init.body) });
    const request = deferredDocumentResponse(); pending.push(request); return request.promise;
  });
  const alpha = writeTestWorkflow('alpha'); const beta = writeTestWorkflow('beta');
  harness.documentSession(alpha.id).setRattishEditorState({ document: writeTestDocument('alpha') });
  harness.documentSession(beta.id).setRattishEditorState({ document: writeTestDocument('beta') });
  const first = harness.mutateActiveRattish([{ kind: 'first' }], alpha);
  const second = harness.mutateActiveRattish([{ kind: 'second' }], alpha);
  const other = harness.mutateActiveRattish([{ kind: 'other' }], beta);
  await new Promise(resolve => setImmediate(resolve));
  assert.deepEqual(calls.map(item => item.url), ['/workflows/alpha/document/mutate', '/workflows/beta/document/mutate']);
  pending[0].resolve(writeTestDocument('alpha first', 'r2'));
  pending[1].resolve(writeTestDocument('beta other', 'b2'));
  await first; await other; await new Promise(resolve => setImmediate(resolve));
  assert.equal(calls[2].url, '/workflows/alpha/document/mutate');
  assert.equal(calls[2].body.expectedRevision, 'r2');
  pending[2].resolve(writeTestDocument('alpha second', 'r3')); await second;
  assert.equal(harness.documentSession('alpha').rattishEditorStateRef.current.document.savedRevision, 'r3');
  assert.equal(harness.documentSession('beta').rattishEditorStateRef.current.document.savedRevision, 'b2');
});

// A fake workflow.rattish on disk for graph Undo and Redo: mutate and save advance its
// revision, and a save against an older revision gets 409 like the real server.
const UNDO_BEFORE = 'Rattish: 1\nWorkflow:\n  name: Picker\n\nprepare:\n  type: bash-command\n\nfetch:\n  type: bash-command\n';
const UNDO_AFTER = 'Rattish: 1\nWorkflow:\n  name: Picker\n\nprepare:\n  type: bash-command\n';

function graphUndoFixture() {
  const workflow = { ...workflowFixture({ id: 'undo-demo', name: 'Undo demo' }), sourceFormat: 'rattish', sourcePath: '/workspace/.raticode/undo-demo/workflow.rattish' };
  const disk = { source: UNDO_BEFORE, revision: 1 };
  const documentFor = () => {
    const nodes = [pickerGraphNode('prepare', 'bash-command'), ...(disk.source.includes('fetch:') ? [pickerGraphNode('fetch', 'bash-command')] : [])];
    return { ...pickerDocument(nodes), source: disk.source, workflowId: workflow.id, compilation: { state: 'valid' }, runnable: true,
      diagnostics: [], preflight: { diagnostics: [] }, savedRevision: `r${disk.revision}`, dirty: false };
  };
  const writes = [];
  const fetchMock = createFetchMock([
    jsonResponse('/api/workflows', workflowsPayload([workflow])),
    (url, options = {}) => url === '/api/workflows/undo-demo/document' && (options.method ?? 'GET') === 'GET'
      ? { ok: true, status: 200, json: async () => ({ document: documentFor() }) } : null,
    (url, options = {}) => {
      const kind = { '/api/workflows/undo-demo/document/mutate': 'mutate', '/api/workflows/undo-demo/document/save': 'save' }[url];
      if (!kind || options.method !== 'POST') return null;
      const body = JSON.parse(options.body);
      writes.push({ kind, body });
      if (body.expectedRevision !== `r${disk.revision}`) return { ok: false, status: 409, json: async () => ({ error: 'workflow.rattish changed on disk' }) };
      if (kind === 'mutate') {
        assert.deepEqual(body.mutations, [{ kind: 'delete_node', node: 'fetch' }]);
        disk.source = UNDO_AFTER;
      } else {
        disk.source = body.source;
      }
      disk.revision += 1;
      return { ok: true, status: 200, json: async () => ({ document: documentFor() }) };
    },
  ]);
  return { disk, fetchMock, writes };
}

async function deleteGraphNode(dom, nodeId) {
  await dom.pointer(dom.ancestor(dom.byExactText(nodeId), 'ARTICLE'), 'onPointerDown');
  await dom.flush();
  await dom.click(dom.byTitle('Delete selected node'));
  for (let index = 0; index < 4; index += 1) await dom.flush();
}

async function pressGraphKey(dom, target, patch) {
  await dom.dispatchWindow('keydown', { key: 'z', code: 'KeyZ', ctrlKey: true, target, ...patch });
  for (let index = 0; index < 4; index += 1) await dom.flush();
}

test('Ctrl+Z on the graph undoes a node delete by saving the text from before it, and Ctrl+Shift+Z deletes it again', async () => {
  const { fetchMock, writes } = graphUndoFixture();
  const dom = await mountReact(React.createElement(appModule.default), fetchMock);
  try {
    await dom.flush(); await dom.flush();
    assert.equal(Boolean(reactProps(dom.byLabel('Nothing to undo')).disabled), true);
    assert.equal(Boolean(reactProps(dom.byLabel('Nothing to redo')).disabled), true);

    await deleteGraphNode(dom, 'fetch');
    assert.deepEqual(writes.map(write => write.kind), ['mutate']);
    const undoButton = dom.byLabel('Undo delete node fetch');
    assert.equal(Boolean(reactProps(undoButton).disabled), false);
    assert.equal(undoButton.getAttribute('title'), 'Undo delete node fetch');

    // A text field keeps its own undo: Ctrl+Z there leaves the graph alone.
    const textField = allElements(dom.container).find(element => element.tagName === 'TEXTAREA');
    assert.ok(textField);
    await pressGraphKey(dom, textField);
    assert.deepEqual(writes.map(write => write.kind), ['mutate']);

    const graph = dom.byLabel('Workflow graph visualization');
    await pressGraphKey(dom, graph);
    assert.deepEqual(writes.map(write => write.kind), ['mutate', 'save']);
    assert.equal(writes[1].body.source, UNDO_BEFORE);
    assert.equal(writes[1].body.expectedRevision, 'r2');
    assert.ok(dom.byExactText('fetch'), 'the deleted node is back on the graph');
    assert.match(dom.text(), /Undid delete node fetch/);
    assert.equal(Boolean(reactProps(dom.byLabel('Redo delete node fetch')).disabled), false);
    assert.equal(Boolean(reactProps(dom.byLabel('Nothing to undo')).disabled), true);

    await pressGraphKey(dom, graph, { key: 'Z', shiftKey: true });
    assert.deepEqual(writes.map(write => write.kind), ['mutate', 'save', 'save']);
    assert.equal(writes[2].body.source, UNDO_AFTER);
    assert.equal(writes[2].body.expectedRevision, 'r3');
    assert.equal(allElements(dom.container).some(element => directText(element) === 'fetch'), false);
    assert.equal(Boolean(reactProps(dom.byLabel('Undo delete node fetch')).disabled), false);
    assert.equal(Boolean(reactProps(dom.byLabel('Nothing to redo')).disabled), true);

    // Edit > Undo acts on the graph while it's in front.
    await dom.click(allElements(dom.container).find(element => element.getAttribute?.('data-menu-trigger') === 'Edit'));
    const editMenu = allElements(dom.container).find(element => element.getAttribute?.('role') === 'menu');
    await dom.click(allElements(editMenu).find(element => element.getAttribute?.('role') === 'menuitem' && textOf(element).startsWith('Undo')));
    for (let index = 0; index < 4; index += 1) await dom.flush();
    assert.deepEqual(writes.map(write => write.kind), ['mutate', 'save', 'save', 'save']);
    assert.equal(writes[3].body.source, UNDO_BEFORE);
    assert.equal(writes[3].body.expectedRevision, 'r4');
  } finally {
    await dom.unmount();
  }
});

test('Edit > Undo undoes typing in a text field that had focus, and goes back to the graph once the graph has focus', async () => {
  const { fetchMock, writes } = graphUndoFixture();
  const edits = [];
  const dom = await mountReact(React.createElement(appModule.default), fetchMock, { desktop: { editFocused: async method => { edits.push(method); } } });
  const editMenuUndo = async (focused) => {
    // The menu remembers the field that had focus when it was pressed, before taking focus itself.
    await dom.focus(focused);
    const trigger = allElements(dom.container).find(element => element.getAttribute?.('data-menu-trigger') === 'Edit');
    await dom.pointer(trigger, 'onPointerDown');
    await dom.focus(trigger);
    await dom.click(trigger);
    const menu = allElements(dom.container).find(element => element.getAttribute?.('role') === 'menu');
    await dom.click(allElements(menu).find(element => element.getAttribute?.('role') === 'menuitem' && textOf(element).startsWith('Undo')));
    for (let index = 0; index < 4; index += 1) await dom.flush();
  };
  try {
    await dom.flush(); await dom.flush();
    await deleteGraphNode(dom, 'fetch');
    const inspector = dom.byLabel('Rattish workflow settings and node inspector');
    const field = allElements(inspector).find(element => element.tagName === 'INPUT' && element.getAttribute('type') !== 'file');
    assert.ok(field);
    Object.defineProperty(field, 'isConnected', { value: true });

    await editMenuUndo(field);
    assert.deepEqual(edits, ['undo'], 'the text field undid its own typing');
    assert.deepEqual(writes.map(write => write.kind), ['mutate'], 'no graph Undo while a text field had focus');
    assert.equal(Boolean(reactProps(dom.byLabel('Undo delete node fetch')).disabled), false);

    await editMenuUndo(dom.byLabel('Workflow graph visualization'));
    assert.deepEqual(edits, ['undo']);
    assert.deepEqual(writes.map(write => write.kind), ['mutate', 'save']);
    assert.equal(writes[1].body.source, UNDO_BEFORE);
  } finally {
    await dom.unmount();
  }
});

test('Ctrl+Z sends no save and says why after workflow.rattish changed since the graph edit', async () => {
  const { disk, fetchMock, writes } = graphUndoFixture();
  const dom = await mountReact(React.createElement(appModule.default), fetchMock);
  try {
    await dom.flush(); await dom.flush();
    await deleteGraphNode(dom, 'fetch');
    assert.equal(Boolean(reactProps(dom.byLabel('Undo delete node fetch')).disabled), false);

    // Rem edits the file; running the workflow picks up the new revision first.
    disk.source = `${UNDO_AFTER}# edited by Rem\n`;
    disk.revision += 1;
    await dom.click(dom.byTitle('Run workflow now'));
    for (let index = 0; index < 4; index += 1) await dom.flush();

    await pressGraphKey(dom, dom.byLabel('Workflow graph visualization'));
    assert.deepEqual(writes.map(write => write.kind), ['mutate']);
    assert.match(dom.text(), /workflow\.rattish changed since that edit, so it can't be undone here/);
    assert.equal(Boolean(reactProps(dom.byLabel('Nothing to undo')).disabled), true);
    assert.equal(Boolean(reactProps(dom.byLabel('Nothing to redo')).disabled), true);
  } finally {
    await dom.unmount();
  }
});

// A fake workflow.rattish for Copy and Paste: the graph's nodes carry the byte spans of
// their declarations, and a paste_nodes mutation appends renamed copies like the backend.
const PASTE_BEFORE = 'Rattish: 1\nWorkflow:\n  name: Picker\n\nNode prepare:\n  type: bash-command\n  command: echo prepare\n  to: fetch\n\nNode fetch:\n  type: bash-command\n  command: echo fetch\n';
const PASTE_COPIED = 'Node prepare:\n  type: bash-command\n  command: echo prepare\n  to: fetch\n\nNode fetch:\n  type: bash-command\n  command: echo fetch\n';

function pasteGraphFixture() {
  const workflow = { ...workflowFixture({ id: 'paste-demo', name: 'Paste demo' }), sourceFormat: 'rattish', sourcePath: '/workspace/.raticode/paste-demo/workflow.rattish' };
  const disk = { source: PASTE_BEFORE, revision: 1, pastedNodes: null };
  const documentFor = () => {
    const declarations = [...disk.source.matchAll(/^Node ([a-z-]+):\n(?: {2}.*\n)*/gm)];
    const nodes = declarations.map((match, index) => ({
      ...pickerGraphNode(match[1], 'bash-command'),
      declarationIndex: index,
      sourceSpan: { start: { offset: match.index }, end: { offset: match.index + match[0].length } },
    }));
    const edges = declarations.flatMap((match) => [...match[0].matchAll(/ to: ([a-z-]+)/g)].map((route, index) => ({
      id: `${match[1]}:route:${index}`, from: match[1], to: route[1], mode: 'unconditional',
    })));
    const positions = { prepare: { x: 100, y: 100 }, fetch: { x: 430, y: 100 } };
    return {
      ...pickerDocument(nodes, edges), source: disk.source, workflowId: workflow.id, compilation: { state: 'valid' }, runnable: true,
      metadata: { canvas: { nodes: positions } }, diagnostics: [], preflight: { diagnostics: [] }, savedRevision: `r${disk.revision}`, dirty: false,
      ...(disk.pastedNodes ? { pastedNodes: disk.pastedNodes } : {}),
    };
  };
  const writes = [];
  const fetchMock = createFetchMock([
    jsonResponse('/api/workflows', workflowsPayload([workflow])),
    (url, options = {}) => url === '/api/workflows/paste-demo/document' && (options.method ?? 'GET') === 'GET'
      ? { ok: true, status: 200, json: async () => ({ document: documentFor() }) } : null,
    (url, options = {}) => {
      const kind = { '/api/workflows/paste-demo/document/mutate': 'mutate', '/api/workflows/paste-demo/document/save': 'save' }[url];
      if (!kind || options.method !== 'POST') return null;
      const body = JSON.parse(options.body);
      writes.push({ kind, body });
      if (body.expectedRevision !== `r${disk.revision}`) return { ok: false, status: 409, json: async () => ({ error: 'workflow.rattish changed on disk' }) };
      disk.pastedNodes = null;
      if (kind === 'mutate') {
        assert.deepEqual(body.mutations, [{ kind: 'paste_nodes', source: PASTE_COPIED }]);
        disk.source = `${disk.source}\n${PASTE_COPIED.replace(/prepare/g, 'prepare-copy').replace(/fetch/g, 'fetch-copy')}`;
        disk.pastedNodes = ['prepare-copy', 'fetch-copy'];
      } else {
        disk.source = body.source;
      }
      disk.revision += 1;
      return { ok: true, status: 200, json: async () => ({ document: documentFor() }) };
    },
  ]);
  return { disk, fetchMock, writes };
}

test('Ctrl+C then Ctrl+V on two selected graph nodes pastes renamed copies beside them as one edit that one Undo takes back', async () => {
  const { disk, fetchMock, writes } = pasteGraphFixture();
  let clipboard = '';
  const clipboardWrites = [];
  const dom = await mountReact(React.createElement(appModule.default), fetchMock, { desktop: { clipboard: { readText: async () => clipboard } } });
  navigator.clipboard.writeText = async (value) => { clipboardWrites.push(value); clipboard = value; };
  const press = async (code, patch = {}) => {
    await dom.dispatchWindow('keydown', { key: code.slice(3).toLowerCase(), code, ctrlKey: true, target: dom.byLabel('Workflow graph visualization'), ...patch });
    for (let index = 0; index < 6; index += 1) await dom.flush();
  };
  const article = (nodeId) => dom.ancestor(dom.byExactText(nodeId), 'ARTICLE');
  try {
    await dom.flush(); await dom.flush();
    await press('KeyA');
    assert.equal(article('prepare').getAttribute('data-selected'), 'true');
    assert.equal(article('fetch').getAttribute('data-selected'), 'true');

    await press('KeyC');
    assert.deepEqual(clipboardWrites, [PASTE_COPIED], 'Copy puts the declarations on the clipboard as plain text');
    assert.deepEqual(writes, [], 'Copy leaves workflow.rattish alone');

    await press('KeyV');
    assert.deepEqual(writes.map((write) => write.kind), ['mutate'], 'one paste_nodes mutation');
    assert.equal(article('prepare-copy').getAttribute('data-selected'), 'true');
    assert.equal(article('fetch-copy').getAttribute('data-selected'), 'true');
    assert.equal(article('prepare').getAttribute('data-selected'), null);
    assert.equal(article('fetch').getAttribute('data-selected'), null);
    // The copies keep their spacing and sit to the right of the nodes they were copied beside.
    assert.deepEqual([article('prepare-copy').style.left, article('prepare-copy').style.top], ['730px', '100px']);
    assert.deepEqual([article('fetch-copy').style.left, article('fetch-copy').style.top], ['1060px', '100px']);
    assert.equal(dom.byLabel('Undo paste 2 nodes').getAttribute('title'), 'Undo paste 2 nodes');

    await press('KeyZ');
    assert.deepEqual(writes.map((write) => write.kind), ['mutate', 'save']);
    assert.equal(writes[1].body.source, PASTE_BEFORE);
    assert.equal(disk.source, PASTE_BEFORE, 'one Undo restores the old workflow.rattish');
    assert.equal(allElements(dom.container).some((element) => directText(element) === 'prepare-copy'), false);
  } finally {
    await dom.unmount();
  }
});

