test("forking an earlier message preserves the original and sends only the copied history", async () => {
  const parent = { id: "fork-parent", title: "Original debugging", projectRoot: "/repo", projectName: "repo", provider: "codex", model: "cli-default", effort: "", resources: { shell: true, web: false, skills: [], mcpServers: [] }, permissionsByProvider: { codex: "workspace-write" }, updatedAt: new Date().toISOString() };
  const history = [
    { id: "first", role: "user", body: "First question" },
    { id: "thought", role: "assistant", kind: "thought", body: "Checking the files", groupId: "trace" },
    { id: "tool", role: "assistant", kind: "thought", body: "Read file", groupId: "trace", trace: { id: "read", kind: "tool", title: "Read file", status: "complete" } },
    { id: "status", role: "system", kind: "system", body: "Context compacted" },
    { id: "error", role: "assistant", kind: "error", body: "Earlier error" },
    { id: "answer", role: "assistant", kind: "final", body: "First answer" },
    { id: "summary", role: "assistant", kind: "turn-summary", body: "", durationMs: 1000 },
    { id: "later", role: "user", body: "Later question" },
    { id: "future", role: "assistant", body: "Future answer" },
  ];
  const fetchMock = createFetchMock([
    jsonResponse("/api/provider/capabilities", { providers: [{ id: "codex", available: true, models: [] }] }),
    url => url === "/api/chat/stream" ? streamResponse(['{"type":"final","message":{"body":"Fork answer"}}\n'])(url) : null,
  ]);
  const dom = await mountReact(React.createElement(chatPaneModule.ChatPane, { activeProjectRoot: "/repo", width: 380 }), fetchMock, { storage: {
    "gofer-flow-chat-threads": JSON.stringify([parent]),
    "gofer-flow-chat-thread-meta:fork-parent": JSON.stringify(parent),
    "gofer-flow-chat-thread:fork-parent": JSON.stringify(history),
  } });
  try {
    await dom.click(dom.ancestor(dom.byText(parent.title), "BUTTON")); await dom.flush();
    const forks = allElements(dom.container).filter(element => element.getAttribute("aria-label") === "Fork thread from here");
    assert.equal(forks.length, 4, dom.text());
    await dom.click(forks[1]); await dom.flush();
    const child = chatThreadsModule.loadChatThreads().find(thread => thread.forkedFromThreadId === parent.id);
    assert.ok(child);
    assert.equal(child.provider, parent.provider);
    assert.deepEqual(child.resources, parent.resources);
    assert.equal(child.forkedFromMessageId, "answer");
    assert.match(dom.text(), /First answer/);
    assert.doesNotMatch(dom.text(), /Future answer|Later question/);
    assert.equal(fetchMock.calls.filter(call => call.url === "/api/chat/stream").length, 0);
    await dom.change(dom.first("textarea"), "Explore another approach");
    await dom.keyDown(dom.first("textarea"), "Enter"); await dom.flush();
    const request = JSON.parse(fetchMock.calls.find(call => call.url === "/api/chat/stream").options.body);
    assert.equal(request.conversationId, child.id);
    assert.equal(request.forkedFrom, parent.id);
    // Narration and tool steps are not re-sent to the new session.
    assert.deepEqual(request.messages.map(message => message.body), ["First question", "Context compacted", "First answer", "Explore another approach"]);
    assert.deepEqual(JSON.parse(window.localStorage.getItem("gofer-flow-chat-thread:fork-parent")), history);
  } finally { await dom.unmount(); }
});

for (const body of ["Repeat this question", ""]) {
  test(`forking a user message automatically sends it once with earlier context and attachments: ${body || "attachment only"}`, async () => {
    const parent = { id: "replay-parent", title: "Original", updatedAt: new Date().toISOString(), projectRoot: "/repo", provider: "codex", model: "cli-default", resources: { shell: true, web: false, skills: [], mcpServers: [] }, permissionsByProvider: { codex: "workspace-write" } };
    const attachment = { id: "file", name: "context.txt", type: "text/plain", size: 7, storageName: "stored-context.txt" };
    const history = [
      { id: "first", role: "user", body: "Earlier question" },
      { id: "answer", role: "assistant", kind: "final", body: "Earlier answer" },
      { id: "selected", role: "user", body, attachments: [attachment] },
      { id: "future", role: "assistant", kind: "final", body: "Do not include this answer" },
    ];
    const fetchMock = createFetchMock([
      jsonResponse("/api/provider/capabilities", { providers: [{ id: "codex", available: true, models: [] }] }),
      jsonResponse("/api/chat/attachments/copy", { attachments: [attachment] }, { method: "POST" }),
      url => url === "/api/chat/stream" ? streamResponse(['{"type":"final","message":{"body":"New fork reply"}}\n'])(url) : null,
    ]);
    const dom = await mountReact(React.createElement(chatPaneModule.ChatPane, { activeProjectRoot: "/repo", width: 380 }), fetchMock, { storage: {
      "gofer-flow-chat-threads": JSON.stringify([parent]),
      "gofer-flow-chat-thread-meta:replay-parent": JSON.stringify(parent),
      "gofer-flow-chat-thread:replay-parent": JSON.stringify(history),
    } });
    try {
      await dom.click(dom.ancestor(dom.byText(parent.title), "BUTTON")); await dom.flush();
      const forks = allElements(dom.container).filter(element => element.getAttribute("aria-label") === "Fork thread from here");
      await dom.click(forks[2]); await dom.flush();
      const child = chatThreadsModule.loadChatThreads().find(thread => thread.forkedFromThreadId === parent.id);
      assert.ok(child);
      assert.equal(child.forkedFromMessageId, "selected");
      const calls = fetchMock.calls.filter(call => call.url === "/api/chat/stream");
      assert.equal(calls.length, 1);
      const request = JSON.parse(calls[0].options.body);
      assert.equal(request.conversationId, child.id);
      assert.equal(request.provider, parent.provider);
      assert.equal(request.permissionMode, "workspace-write");
      assert.deepEqual(request.messages.map(message => message.body), ["Earlier question", "Earlier answer", body]);
      assert.deepEqual(request.messages.at(-1).attachments, [attachment]);
      const copy = JSON.parse(fetchMock.calls.find(call => call.url === "/api/chat/attachments/copy").options.body);
      assert.deepEqual(copy, { sourceThreadId: parent.id, threadId: child.id, attachments: [attachment] });
      assert.match(dom.text(), /New fork reply/);
      assert.doesNotMatch(dom.text(), /Do not include this answer/);
      assert.deepEqual(JSON.parse(window.localStorage.getItem("gofer-flow-chat-thread:replay-parent")), history);
      const childHistory = JSON.parse(window.localStorage.getItem(`gofer-flow-chat-thread:${child.id}`));
      assert.equal(childHistory.filter(message => message.id === "selected").length, 1);
    } finally { await dom.unmount(); }
  });
}

test("thread order changes on user submission and completion, never streamed thoughts or history saves", async () => {
  const first = controlledStreamResponse([
    '{"type":"thought","text":"Inspecting the files"}\n',
    '{"type":"thought","text":"More assistant commentary"}\n',
    '{"type":"final","message":{"body":"First completed"}}\n',
  ]);
  const second = controlledStreamResponse(['{"type":"final","message":{"body":"Second completed"}}\n']);
  const followup = controlledStreamResponse(['{"type":"final","message":{"body":"Followup completed"}}\n']);
  const streams = [first, second, followup];
  let submitted = 0;
  const fetchMock = createFetchMock([
    jsonResponse("/api/provider/capabilities", { providers: [{ id: "codex", available: true, models: [] }] }),
    url => url === "/api/chat/stream" ? streams[submitted++].response(url) : null,
  ]);
  const dom = await mountReact(React.createElement(chatPaneModule.ChatPane, { width: 380 }), fetchMock);
  const ids = () => allElements(dom.container).map(el => el.getAttribute("data-thread-id")).filter(Boolean);
  const savedTime = id => JSON.parse(window.localStorage.getItem(`gofer-flow-chat-thread-meta:${id}`)).updatedAt;
  try {
    await dom.flush();
    await dom.change(dom.first("textarea"), "First task");
    await dom.keyDown(dom.first("textarea"), "Enter", { ctrlKey: true });
    await dom.flush();
    // Background threads wait in the collapsed Running group.
    assert.deepEqual(ids(), []);
    await openThreadGroup(dom, "Running");
    const firstId = ids()[0];
    await dom.change(dom.first("textarea"), "Second task");
    await dom.keyDown(dom.first("textarea"), "Enter", { ctrlKey: true });
    await dom.flush();
    const secondId = ids()[0];
    assert.notEqual(firstId, secondId);
    const timestamp = savedTime(firstId);
    for (let i = 0; i < 2; i++) {
      first.releaseNext(); await dom.flush();
      assert.deepEqual(ids(), [secondId, firstId]);
      assert.equal(savedTime(firstId), timestamp);
    }
    first.releaseNext(); await dom.flush();
    assert.deepEqual(ids(), [firstId, secondId]);
    second.releaseNext(); await dom.flush();
    assert.deepEqual(ids(), [secondId, firstId]);
    const row = allElements(dom.container).find(el => el.getAttribute("data-thread-id") === firstId);
    await dom.click(allElements(row).find(el => el.tagName === "BUTTON"));
    await dom.flush();
    await dom.change(dom.first("textarea"), "Follow up on the first task");
    await dom.keyDown(dom.first("textarea"), "Enter");
    await dom.flush();
    await dom.click(dom.byLabel("Back to active threads"));
    await dom.flush();
    // The unread second thread stays above the running follow-up.
    assert.deepEqual(ids(), [secondId]);
    await openThreadGroup(dom, "Running");
    assert.deepEqual(ids(), [secondId, firstId]);
    followup.releaseNext(); await dom.flush();
    assert.deepEqual(ids(), [firstId, secondId]);
  } finally {
    for (const stream of streams) for (let i = 0; i < 3; i++) stream.releaseNext();
    await dom.flush(); await dom.unmount();
  }
});

test("provider model checklist hides and shows models, persists, and hides denied configured options", async () => {
  const settings = await viteServer.ssrLoadModule("/src/components/ProviderSettings.jsx");
  const picker = await viteServer.ssrLoadModule("/src/components/ProviderModelEffortFields.jsx");
  let deniedModels = [];
  let failSave = false;
  const discoveredModels = [{ id: "sol", displayName: "Sol" }, { id: "astra", displayName: "Astra" }];
  function catalog() {
    return [{ id: "codex", displayName: "Codex", available: true, discoveryStatus: "ready", enabled: true,
      defaultModel: deniedModels.includes("sol") ? "astra" : "sol", defaultModelOverride: "sol",
      deniedModels, discoveredModels, models: discoveredModels.filter(model => !deniedModels.includes(model.id)) }];
  }
  function Harness() {
    const state = picker.useProviderCapabilities();
    return React.createElement(React.Fragment, null,
      React.createElement(settings.default, { providerState: state }),
      React.createElement(picker.ProviderModelEffortFields, { ...state, provider: "codex", model: "sol", onChange() {} }));
  }
  const fetchMock = createFetchMock([(url, options) => {
    if (url.startsWith("/api/provider/capabilities")) return { ok: true, json: async () => ({ providers: catalog() }) };
    if (url === "/api/provider/commit-settings") return { ok: true, json: async () => ({}) };
    if (url === "/api/provider/settings") {
      if (failSave) return { ok: false, json: async () => ({ error: "Could not save models" }) };
      deniedModels = JSON.parse(options.body).deniedModels;
      return { ok: true, json: async () => ({ saved: true }) };
    }
    return null;
  }]);
  let dom = await mountReact(React.createElement(Harness), fetchMock);
  const dispatch = event => { for (const listener of document.listeners[event.type] ?? []) listener(event); return true; };
  window.dispatchEvent = dispatch;
  const shown = name => reactProps(dom.byLabel(`Show ${name} in model menus`)).checked;
  const toggle = async (name, value) => { await dom.change(dom.byLabel(`Show ${name} in model menus`), value); await dom.flush(); };
  const button = text => allElements(dom.container).find(el => el.tagName === "BUTTON" && textOf(el) === text);
  function options(label) { return allElements(dom.byLabel(label)).filter(el => el.tagName === "OPTION").map(el => reactProps(el).value); }
  try {
    await dom.flush();
    await openProviderDetails(dom, "codex");
    assert.match(dom.text(), /Show in model menus/);
    assert.match(dom.text(), /2 of 2 shown/);
    assert.doesNotMatch(dom.text(), /arrows/);
    assert.throws(() => dom.byLabel("Search Codex models"), /Unable to find/, "two models need no search field");
    assert.equal(reactProps(button("Show all")).disabled, true);
    await toggle("Sol", false);
    assert.deepEqual(deniedModels, ["sol"]);
    assert.equal(shown("Sol"), false);
    assert.equal(shown("Astra"), true);
    assert.match(dom.text(), /1 of 2 shown/);
    assert.ok(!options("Codex default model").includes("sol"));
    await dom.click(allElements(dom.container).find(el => el.getAttribute?.("data-picker-trigger") === "model"));
    const menu = dom.byLabel("Model options");
    assert.doesNotMatch(textOf(menu), /Sol|sol.*configured/);
    assert.match(textOf(menu), /Astra/);
    await dom.unmount();
    dom = await mountReact(React.createElement(Harness), fetchMock);
    window.dispatchEvent = dispatch;
    await dom.flush();
    await openProviderDetails(dom, "codex");
    assert.equal(shown("Sol"), false);
    failSave = true;
    await toggle("Sol", true);
    assert.match(dom.text(), /Could not save models/);
    assert.equal(shown("Sol"), false);
    failSave = false;
    await toggle("Sol", true);
    assert.deepEqual(deniedModels, []);
    assert.equal(shown("Sol"), true);
    await dom.click(button("Hide all")); await dom.flush();
    assert.deepEqual([...deniedModels].sort(), ["astra", "sol"]);
    assert.match(dom.text(), /0 of 2 shown/);
    assert.match(dom.text(), /All models are denied/);
    assert.equal(reactProps(button("Hide all")).disabled, true);
    await dom.click(button("Show all")); await dom.flush();
    assert.deepEqual(deniedModels, []);
    assert.match(dom.text(), /2 of 2 shown/);
  } finally { await dom.unmount(); }
});

test("provider model checklist searches long model lists and says when none are discovered", async () => {
  const settings = await viteServer.ssrLoadModule("/src/components/ProviderSettings.jsx");
  const discoveredModels = Array.from({ length: 9 }, (_, index) => ({ id: `model-${index + 1}`, displayName: `Model ${index + 1}` }));
  discoveredModels[8] = { id: "gpt-mini", displayName: "Mini" };
  const providerState = { loading: false, refresh() {}, capabilities: [
    { id: "codex", displayName: "Codex", available: true, discoveryStatus: "ready", enabled: true, deniedModels: ["model-2"], discoveredModels, models: discoveredModels },
    { id: "cursor", displayName: "Cursor", available: true, discoveryStatus: "ready", enabled: true, deniedModels: [], models: [] },
  ] };
  const fetchMock = createFetchMock([() => null]);
  const dom = await mountReact(React.createElement(settings.default, { providerState }), fetchMock);
  const rows = () => allElements(dom.container).filter(el => el.tagName === "INPUT" && /^Show .* in model menus$/.test(el.getAttribute("aria-label") ?? ""));
  try {
    await dom.flush();
    await openProviderDetails(dom, "codex");
    await openProviderDetails(dom, "cursor");
    assert.match(dom.text(), /8 of 9 shown/);
    assert.equal(rows().length, 9);
    // The ID is the secondary text under the display name.
    assert.match(dom.text(), /Minigpt-mini/);
    await dom.change(dom.byLabel("Search Codex models"), "GPT");
    assert.deepEqual(rows().map(el => el.getAttribute("aria-label")), ["Show Mini in model menus"]);
    await dom.change(dom.byLabel("Search Codex models"), "model 2");
    assert.deepEqual(rows().map(el => el.getAttribute("aria-label")), ["Show Model 2 in model menus"]);
    assert.equal(reactProps(rows()[0]).checked, false);
    await dom.change(dom.byLabel("Search Codex models"), "nothing like this");
    assert.equal(rows().length, 0);
    assert.match(dom.text(), /No models match/);
    assert.match(dom.text(), /8 of 9 shown/, "the count covers every model, not just matches");
    assert.match(dom.text(), /No models discovered yet\. Refresh providers after signing in\./);
    assert.throws(() => dom.byLabel("Search Cursor models"), /Unable to find/);
  } finally { await dom.unmount(); }
});

test("dedicated commit provider and model persist independently, report failures, and reset", async () => {
  const settings = await viteServer.ssrLoadModule("/src/components/CommitMessageSettings.jsx");
  let stored = {};
  let failSave = false;
  const providerState = { loading: false, refresh() {}, capabilities: [
    { id: "codex", displayName: "Codex", enabled: true, available: true, discoveryStatus: "ready", defaultModel: "sol", models: [{ id: "sol", displayName: "Sol" }, { id: "astra", displayName: "Astra" }], deniedModels: ["denied"] },
    { id: "cursor", displayName: "Cursor", enabled: true, available: true, discoveryStatus: "ready", defaultModel: "auto", models: [{ id: "auto" }] },
  ] };
  const fetchMock = createFetchMock([(url, options) => {
    if (url !== "/api/provider/commit-settings") return null;
    if (options?.method === "POST") {
      if (failSave) return { ok: false, json: async () => ({ error: "Could not save commit settings" }) };
      stored = JSON.parse(options.body);
      return { ok: true, json: async () => ({ saved: true }) };
    }
    return { ok: true, json: async () => stored };
  }]);
  let dom = await mountReact(React.createElement(settings.default, { capabilities: providerState.capabilities }), fetchMock);
  try {
    await dom.flush();
    await dom.change(dom.byLabel("Commit message provider"), "codex"); await dom.flush();
    assert.deepEqual(stored, { provider: "codex", model: "sol" });
    await dom.change(dom.byLabel("Commit message model"), "astra"); await dom.flush();
    assert.deepEqual(stored, { provider: "codex", model: "astra" });
    await dom.unmount();
    dom = await mountReact(React.createElement(settings.default, { capabilities: providerState.capabilities }), fetchMock);
    await dom.flush();
    assert.equal(reactProps(dom.byLabel("Commit message model")).value, "astra");
    assert.doesNotMatch(textOf(dom.byLabel("Commit message model")), /denied/);
    failSave = true;
    await dom.change(dom.byLabel("Commit message provider"), "cursor"); await dom.flush();
    assert.equal(reactProps(dom.byLabel("Commit message provider")).value, "codex");
    assert.match(dom.text(), /Could not save commit settings/);
    failSave = false;
    await dom.change(dom.byLabel("Commit message provider"), ""); await dom.flush();
    assert.deepEqual(stored, { provider: "", model: "" });
    assert.ok(!allElements(dom.container).some(el => el.getAttribute?.("aria-label") === "Commit message model"));
  } finally { await dom.unmount(); }
});

test("voice tidy settings start from the default provider's fast model and explain why it can't run", async () => {
  const settings = await viteServer.ssrLoadModule("/src/components/VoiceTidySettings.jsx");
  const capabilities = [
    { id: "claude_code", displayName: "Claude Code", enabled: true, available: true, models: [{ id: "claude-opus-5-5", displayName: "Opus 5.5" }] },
    { id: "codex", displayName: "Codex", enabled: true, available: true, models: [{ id: "gpt-6-luna", displayName: "GPT-6 Luna" }, { id: "gpt-6-astra", displayName: "Astra" }] },
  ];
  let stored = { enabled: false, provider: "", model: "", effort: "", context: true };
  const saves = [];
  const gets = [];
  const resolved = (defaultProvider) => {
    const provider = stored.provider || defaultProvider;
    if (provider === "claude_code") {
      return { provider, followsDefault: !stored.provider, model: "claude-haiku-5-5", label: "Claude Haiku 5.5", providerName: "Claude Code", available: false, context: stored.context,
        reason: "Claude Haiku 5.5 needs Claude Code 2.1.293 or later. Run claude update, then try again." };
    }
    return { provider, followsDefault: !stored.provider, model: stored.model || "gpt-6-luna", label: stored.model ? "Astra" : "GPT-6 Luna", providerName: "Codex", effort: "low", available: true, context: stored.context, reason: "" };
  };
  const fetchMock = createFetchMock([(url, options) => {
    if (!url.startsWith("/api/provider/voice-tidy")) return null;
    if (options?.method === "POST") {
      const changes = JSON.parse(options.body);
      saves.push(changes);
      stored = { ...stored, ...("provider" in changes ? { model: "" } : {}), ...changes };
      return { ok: true, json: async () => ({ saved: true, ...stored }) };
    }
    gets.push(url);
    const query = new URLSearchParams(url.split("?")[1] || "");
    return { ok: true, json: async () => ({ ...stored, selection: resolved(query.get("defaultProvider")) }) };
  }]);
  const dom = await mountReact(React.createElement(settings.default, { capabilities, defaultProvider: "claude_code" }), fetchMock);
  try {
    await dom.flush();
    assert.match(gets[0], /defaultProvider=claude_code/);
    assert.match(textOf(dom.byLabel("Voice tidy provider")), /Same as default provider \(Claude Code\)/);
    assert.match(textOf(dom.byLabel("Voice tidy model")), /Fast model \(Claude Haiku 5\.5\)/);
    assert.match(dom.text(), /needs Claude Code 2\.1\.293 or later\. Run claude update.*Until then your words appear as heard/);
    await React.act(async () => reactProps(dom.byLabel("Tidy voice messages")).onChange({ target: { checked: true } })); await dom.flush();
    assert.deepEqual(saves.at(-1), { enabled: true });
    await dom.change(dom.byLabel("Voice tidy provider"), "codex"); await dom.flush();
    assert.deepEqual(saves.at(-1), { provider: "codex" });
    assert.match(textOf(dom.byLabel("Voice tidy model")), /Fast model \(GPT-6 Luna\)/);
    assert.match(dom.text(), /Uses GPT-6 Luna at low effort\. What you dictate goes to Codex, with names from Rem's chat/);
    await dom.change(dom.byLabel("Voice tidy model"), "gpt-6-astra"); await dom.flush();
    assert.deepEqual(saves.at(-1), { provider: "codex", model: "gpt-6-astra" });
    await React.act(async () => reactProps(dom.byLabel("Use Rem's chat to spell names")).onChange({ target: { checked: false } })); await dom.flush();
    assert.deepEqual(saves.at(-1), { context: false });
    assert.doesNotMatch(dom.text(), /with names from Rem's chat/);
  } finally { await dom.unmount(); }
});

