test("Rem leads the activity rail and Second Brain follows Swarms in arrow-key traversal", async () => {
  const workspace = { trustProjectRoot: async () => {}, listDirectory: async () => ({ entries: [] }), gitStatus: async () => ({ active: false, entries: [] }) };
  const opened = [];
  const remOpened = [];
  const editorShown = [];
  const settings = settingsModule.normalizeAppSettings({ plugins: { enabled: EXPERIMENTAL_PLUGINS_ON } });
  const dom = await mountReact(React.createElement(codeFileExplorerModule.default, { settings, workflow: { projectRoot: "/workspace/project" }, onOpenSecondBrain: () => opened.push(true), onOpenRemHome: () => remOpened.push(true), onShowEditor: () => editorShown.push(true) }), createFetchMock([]), { desktop: { workspace } });
  try {
    const labels = allElements(dom.container).filter(element => String(element.getAttribute?.("id") || "").startsWith("sidebar-tab-")).map(element => element.getAttribute("aria-label"));
    assert.equal(labels[0], "Rem");
    // Organizations stays off until a user turns it on.
    assert.deepEqual(labels.slice(-2), ["Swarms", "Second Brain"]);
    assert.equal(labels.includes("Organizations"), false);
    const rail = { currentTarget: { parentElement: { querySelector: () => null } } };
    await dom.keyDown(dom.byLabel("Swarms"), "ArrowDown", rail);
    assert.equal(dom.byLabel("Second Brain").getAttribute("aria-selected"), "true");
    await dom.keyDown(dom.byLabel("Second Brain"), "ArrowDown", rail);
    assert.equal(dom.byLabel("Rem").getAttribute("aria-selected"), "true");
    await dom.keyDown(dom.byLabel("Rem"), "ArrowDown", rail);
    assert.equal(dom.byLabel("File explorer").getAttribute("aria-selected"), "true");
    await dom.keyDown(dom.byLabel("File explorer"), "End", rail);
    assert.equal(dom.byLabel("Second Brain").getAttribute("aria-selected"), "true");
    // Arrow keys only move between panels; clicking Rem or Second Brain opens its home.
    assert.deepEqual(opened, []);
    assert.deepEqual(remOpened, []);
    await dom.click(dom.byLabel("Rem"));
    assert.deepEqual(remOpened, [true]);
    await dom.click(dom.byLabel("Second Brain"));
    assert.deepEqual(opened, [true]);
    // File explorer shows the editor's tabs on every click, even when already selected.
    assert.deepEqual(editorShown, [], "arrow keys reached File explorer without showing the editor");
    await dom.click(dom.byLabel("File explorer"));
    await dom.click(dom.byLabel("File explorer"));
    assert.deepEqual(editorShown, [true, true]);
  } finally { await dom.unmount(); }
});

test("plugin settings hide, order, and lock the activity rail", async () => {
  const workspace = { trustProjectRoot: async () => {}, listDirectory: async () => ({ entries: [] }), gitStatus: async () => ({ active: false, entries: [] }) };
  const changes = [];
  const settingsFor = (plugins) => settingsModule.normalizeAppSettings({ plugins });
  const railLabels = (dom) => allElements(dom.container).filter(element => String(element.getAttribute?.("id") || "").startsWith("sidebar-tab-")).map(element => element.getAttribute("aria-label"));
  const props = (plugins) => ({
    workflow: { projectRoot: "/workspace/project" },
    settings: settingsFor(plugins),
    sidebarView: "second-brain",
    onSettingsChange: (path, value) => changes.push([path, value]),
  });
  const dom = await mountReact(React.createElement(codeFileExplorerModule.default, props({
    order: ["second-brain", "files", "rem", "search", "source-control", "swarms", "organizations"],
    enabled: { rem: false, files: false, organizations: true, swarms: true, "second-brain": true },
  })), createFetchMock([]), { desktop: { workspace } });
  try {
    // File explorer cannot be turned off; Rem is hidden and Organizations is opted in.
    assert.deepEqual(railLabels(dom), ["Second Brain", "File explorer", "Browser", "Search", "Source control", "Kanban", "Swarms", "Organizations"]);
    const target = dom.byLabel("Swarms");
    const dragEvent = { clientY: 30, currentTarget: { getBoundingClientRect: () => ({ top: 0, height: 40 }) }, dataTransfer: { setData() {} } };
    await dom.pointer(dom.byLabel("Second Brain"), "onDragStart", dragEvent);
    await dom.pointer(target, "onDragOver", dragEvent);
    await dom.pointer(target, "onDrop", dragEvent);
    // Workflows was missing from the stored order, so it returns after Rem, and
    // Browser, newer than the stored order, after File explorer.
    assert.deepEqual(changes.at(-1), ["plugins.order", ["files", "browser", "rem", "workflows", "search", "source-control", "kanban", "posts", "swarms", "second-brain", "organizations"]]);
    const rail = { currentTarget: { parentElement: { querySelector: () => null } } };
    await dom.keyDown(dom.byLabel("Search"), "ArrowUp", { ...rail, altKey: true });
    // Hidden plugins are skipped, so Search moves above Browser.
    assert.deepEqual(changes.at(-1), ["plugins.order", ["second-brain", "files", "search", "browser", "rem", "workflows", "source-control", "kanban", "posts", "swarms", "organizations"]]);
    await dom.click(dom.byLabel("Lock plugin order"));
    assert.deepEqual(changes.at(-1), ["plugins.locked", true]);
  } finally { await dom.unmount(); }

  changes.length = 0;
  const locked = await mountReact(React.createElement(codeFileExplorerModule.default, props({ locked: true, enabled: { "second-brain": false } })), createFetchMock([]), { desktop: { workspace } });
  try {
    // A turned-off plugin cannot keep the sidebar, so it falls back to files.
    assert.equal(locked.byLabel("File explorer").getAttribute("aria-selected"), "true");
    assert.equal(railLabels(locked).includes("Second Brain"), false);
    assert.equal(reactProps(locked.byLabel("Search")).draggable, false);
    assert.equal(locked.byLabel("Lock plugin order").getAttribute("aria-pressed"), "true");
    let prevented = false;
    await locked.pointer(locked.byLabel("Search"), "onDragStart", { preventDefault: () => { prevented = true; } });
    assert.equal(prevented, true);
    await locked.keyDown(locked.byLabel("Search"), "ArrowDown", { currentTarget: { parentElement: { querySelector: () => null } }, altKey: true });
    assert.deepEqual(changes, []);
  } finally { await locked.unmount(); }
});

test("the Plugins settings section toggles, reorders, and restores sidebar plugins", async () => {
  const changes = [];
  let settings = settingsModule.normalizeAppSettings({ plugins: { enabled: {}, preview: { swarms: true } } });
  // Holds settings in state so every click sees the previous change.
  function Harness() {
    const [current, setCurrent] = React.useState(settings);
    return React.createElement(settingsPopoverModule.default, {
      open: true,
      initialCategory: "plugins",
      settings: current,
      onChange: (path, value) => { changes.push([path, value]); settings = settingsModule.updateSetting(settings, path, value); setCurrent(settings); },
      onClose: () => {},
    });
  }
  const render = () => React.createElement(Harness);
  const hasLabel = (dom, label) => allElements(dom.container).some(node => node.getAttribute?.("aria-label") === label);
  const dom = await mountReact(render(), createFetchMock([]));
  try {
    assert.ok(dom.byText("Always shown"));
    assert.doesNotMatch(dom.text(), /Experimental/);
    // Experimental plugins that are off appear only in Feature Preview.
    for (const label of ["Organizations", "Second Brain"]) assert.equal(hasLabel(dom, `Show ${label}`), false, `${label} is hidden while off`);
    assert.equal(dom.byLabel("Show Swarms").getAttribute("aria-checked"), "true");
    // Rem is a standard plugin, listed and shown without a Feature Preview choice.
    assert.equal(dom.byLabel("Show Rem").getAttribute("aria-checked"), "true");
    assert.equal(dom.byLabel("Show Search").getAttribute("aria-checked"), "true");
    await dom.click(dom.byLabel("Show Search"));
    assert.deepEqual(changes.at(-1), ["plugins.enabled", { search: false }]);
    await dom.click(dom.byLabel("Show Rem"));
    assert.deepEqual(changes.at(-1), ["plugins.enabled", { search: false, rem: false }]);
    assert.equal(dom.byLabel("Show Rem").getAttribute("aria-checked"), "false", "the row and its switch stay");
    // Hiding a Feature Preview plugin removes it from the sidebar only.
    await dom.click(dom.byLabel("Show Swarms"));
    assert.deepEqual(changes.at(-1), ["plugins.enabled", { search: false, rem: false, swarms: false }]);
    assert.deepEqual(settings.plugins.preview, { swarms: true });
    assert.equal(dom.byLabel("Show Swarms").getAttribute("aria-checked"), "false", "the row and its switch stay");
    await dom.keyDown(dom.byLabel("Move Rem"), "ArrowDown");
    assert.deepEqual(changes.at(-1), ["plugins.order", ["workflows", "rem", "files", "browser", "search", "source-control", "kanban", "posts", "swarms", "organizations", "second-brain"]]);
  } finally { await dom.unmount(); }

  changes.length = 0;
  settings = settingsModule.normalizeAppSettings({ plugins: { locked: true, order: ["files", "rem"], enabled: { rem: false, search: false }, preview: { swarms: true } } });
  const lockedDom = await mountReact(render(), createFetchMock([]));
  try {
    assert.equal(reactProps(lockedDom.byLabel("Move Rem")).disabled, true);
    await lockedDom.click(lockedDom.byText("Restore defaults"));
    // Restoring sidebar defaults shows every plugin and leaves Feature Preview alone.
    assert.deepEqual(changes, [["plugins.order", settingsModule.DEFAULT_APP_SETTINGS.plugins.order], ["plugins.enabled", {}]]);
    assert.deepEqual(settings.plugins.preview, { swarms: true });
  } finally { await lockedDom.unmount(); }
  assert.deepEqual(settingsPopoverModule.settingsCategoriesForQuery("experimental"), ["developer"]);
  assert.deepEqual(settingsPopoverModule.settingsCategoriesForQuery("feature preview"), ["developer"]);
  assert.ok(settingsPopoverModule.settingsCategoriesForQuery("plugins").includes("plugins"));
});

test("Developer shows a running application log that filters by level, source and text", async () => {
  const at = (minute) => new Date(Date.UTC(2026, 10, 5, 15, minute)).toISOString();
  const server = [
    { seq: 1, time: at(1), level: "info", source: "backend", message: "Backend ready at http://127.0.0.1:41000 after 2.1 s" },
    { seq: 2, time: at(2), level: "debug", source: "devices", message: "A connection over Tailscale closed before identifying itself", component: "gofer.devices.service" },
    { seq: 3, time: at(3), level: "warn", source: "devices", message: "Phone \"Pixel\" could not sign in over Tailscale while checking the device's identity", component: "gofer.devices.service" },
  ];
  const reads = [];
  let missed = 0;
  const developer = {
    info: async () => ({ version: "0.5.1", platform: "darwin arm64", electron: "45", node: "22", backend: "Running", dataDir: "/data", userData: "/user", appLog: "/Users/me/Library/Logs/Raticode/app.jsonl" }),
    action: async () => undefined,
    entries: async ({ after = 0, history = false } = {}) => {
      reads.push({ after, history });
      const entries = server.filter((entry) => entry.seq > after);
      const result = { entries, cursor: entries.at(-1)?.seq ?? after, latest: server.length, more: false, missed, counts: {}, history: history ? { entries: [{ time: new Date(Date.UTC(2026, 10, 5, 14, 0)).toISOString(), level: "error", source: "backend", message: "Backend stopped unexpectedly after 3.0 s (exit code 1)\nTraceback (most recent call last):\nOSError: [Errno 48] Address already in use" }], truncated: false } : null };
      missed = 0;
      return result;
    },
  };
  const element = React.createElement(settingsPopoverModule.default, {
    open: true, initialCategory: "developer", settings: settingsModule.normalizeAppSettings({}), onChange: () => {}, onClose: () => {},
  });
  const dom = await mountReact(element, createFetchMock([]), { desktop: { developer, features: { get: async () => ({}), set: async () => ({}) } } });
  const rowTexts = () => allElements(dom.byLabel("Application log entries")).filter((node) => String(node.getAttribute?.("class") || "").includes("app-log-message")).map(textOf);
  try {
    await dom.flush();
    await dom.flush();
    assert.deepEqual(reads[0], { after: 0, history: true });
    assert.deepEqual(rowTexts(), [
      "Phone \"Pixel\" could not sign in over Tailscale while checking the device's identity",
      "Backend ready at http://127.0.0.1:41000 after 2.1 s",
      "Backend stopped unexpectedly after 3.0 s (exit code 1)+2 lines",
    ], "newest first; debug hidden; a traceback shows its first line and how much more there is");
    assert.ok(dom.byText("Before this launch"));
    assert.equal(dom.byTitle("Show debug").getAttribute("aria-pressed"), "false");
    assert.match(textOf(dom.byTitle("Show errors")), /Errors\s*1/);

    await dom.click(dom.byTitle("Show debug"));
    assert.equal(rowTexts().length, 4);
    await dom.click(dom.byTitle("Show info"));
    assert.ok(!rowTexts().some((text) => text.startsWith("Backend ready")));
    await dom.click(dom.byTitle("Show info"));

    await dom.change(dom.byLabel("Search the log"), "tailscale");
    assert.equal(rowTexts().length, 2);
    await dom.change(dom.byLabel("Search the log"), "");
    await dom.change(dom.controlAfterLabel("Source"), "backend");
    assert.deepEqual(rowTexts(), ["Backend ready at http://127.0.0.1:41000 after 2.1 s", "Backend stopped unexpectedly after 3.0 s (exit code 1)+2 lines"]);
    await dom.change(dom.controlAfterLabel("Source"), "all");

    // New entries arrive on the next poll, with only the new part requested.
    server.push({ seq: 4, time: at(4), level: "info", source: "devices", message: "Phone \"Pixel\" connected over Tailscale (resumed, signed in after 180 ms)" });
    await dom.flush(1000);
    await dom.flush();
    assert.ok(reads.some((read) => read.after === 3 && !read.history));
    assert.equal(rowTexts()[0], "Phone \"Pixel\" connected over Tailscale (resumed, signed in after 180 ms)");

    // Pausing holds the view still and counts what arrives meanwhile.
    await dom.click(dom.byText("Following"));
    server.push({ seq: 5, time: at(5), level: "error", source: "backend", message: "Rem transcription failed" });
    missed = 2;
    await dom.flush(1000);
    await dom.flush();
    assert.ok(dom.byText("Paused, 1 new"));
    assert.ok(!rowTexts().includes("Rem transcription failed"));
    assert.ok(dom.byText("2 entries arrived faster than this view could keep them. They are in the log file."));
    await dom.click(dom.byText("Paused, 1 new"));
    assert.equal(rowTexts()[0], "Rem transcription failed");

    await dom.change(dom.controlAfterLabel("Include earlier launches"), false);
    assert.ok(!rowTexts().some((text) => text.startsWith("Backend stopped unexpectedly")));
    assert.match(dom.text(), /Left out on purpose: message and conversation content/);
  } finally { await dom.unmount(); }
});

