test("Second Brain draft fields keep cleared and partial text until blur", async () => {
  const parts = await viteServer.ssrLoadModule("/src/components/SecondBrainParts.jsx");
  const commits = [];
  function Harness() {
    const [value, setValue] = React.useState("2026");
    // The parent normalizes committed values; the draft must not snap back while focused.
    return React.createElement(parts.DraftInput, { label: "From date", value, onCommit: (next) => { commits.push(next); setValue(next.trim() || "2026"); } });
  }
  const dom = await mountReact(React.createElement(Harness), createFetchMock([]));
  try {
    const input = dom.byLabel("From date");
    await dom.focus(input);
    await dom.change(input, "");
    assert.equal(input.value, "");
    await dom.change(input, "2025-0");
    assert.equal(input.value, "2025-0");
    assert.deepEqual(commits, []);
    await dom.blur(input);
    assert.deepEqual(commits, ["2025-0"]);
    assert.equal(dom.byLabel("From date").value, "2025-0");
    await dom.focus(input);
    await dom.change(input, "");
    await dom.blur(input);
    assert.deepEqual(commits, ["2025-0", ""]);
    assert.equal(dom.byLabel("From date").value, "2026");
  } finally { await dom.unmount(); }
});

test("Rem clear history erases its conversation and task threads but keeps the user's threads", async () => {
  const store = await viteServer.ssrLoadModule("/src/lib/remHomeStore.js");
  store.resetRemHomeStore();
  const created = new Date().toISOString();
  let conversation = { conversation: { id: "old", turn_state: "idle" }, messages: [{ id: "m1", role: "user", created_at: created, body: "Corrupted old request" }] };
  const fetchMock = createFetchMock([
    jsonResponse("/api/workflows", workflowsPayload([])),
    (url) => url === "/api/rem/conversation" ? { ok: true, json: async () => conversation } : null,
    jsonResponse("/api/rem/tasks", { tasks: [] }),
    (url, options) => {
      if (url === "/api/rem/messages" && options.method === "POST") {
        const message = JSON.parse(options.body);
        assert.equal(conversation.conversation.id, "fresh");
        conversation.messages.push({ id: message.request_id, request_id: message.request_id, role: "user", body: message.body, created_at: created });
        return { ok: true, json: async () => ({ conversation: conversation.conversation }) };
      }
      if (url !== "/api/rem/reset" || options.method !== "POST") return null;
      const body = JSON.parse(options.body);
      assert.equal(body.conversation_id, "old");
      assert.equal(body.confirm, true);
      conversation = { conversation: { id: "fresh", turn_state: "idle" }, messages: [] };
      return { ok: true, json: async () => ({ conversation: conversation.conversation, removed_thread_ids: ["rem-worker"] }) };
    },
  ]);
  const dom = await mountReact(React.createElement(appModule.default), fetchMock, { storage: experimentalPluginStorage() });
  try {
    const storage = window.localStorage;
    storage.setItem("gofer-flow-chat-threads", JSON.stringify([{ id: "rem-worker" }, { id: "rem-review" }, { id: "mine" }]));
    storage.setItem("gofer-flow-chat-thread-meta:rem-worker", JSON.stringify({ id: "rem-worker", managedRunId: "run" }));
    storage.setItem("gofer-flow-chat-thread-meta:rem-review", JSON.stringify({ id: "rem-review", managedRunId: "run", managedRole: "verify" }));
    storage.setItem("gofer-flow-chat-thread-meta:mine", JSON.stringify({ id: "mine", title: "My own thread" }));
    await dom.click(dom.byLabel("Rem"));
    for (let attempt = 0; attempt < 20 && !textOf(dom.container).includes("Corrupted old request"); attempt += 1) {
      await new Promise(resolve => setTimeout(resolve, 10));
      await dom.flush();
    }
    await dom.click(dom.byLabel("Rem options"));
    await dom.click(dom.ancestor(dom.byText("Clear history and tasks…"), "BUTTON"));
    await dom.click(dom.ancestor(dom.byText("Clear history and tasks"), "BUTTON"));
    for (let attempt = 0; attempt < 20 && textOf(dom.container).includes("Corrupted old request"); attempt += 1) {
      await new Promise(resolve => setTimeout(resolve, 10));
      await dom.flush();
    }
    assert.equal(fetchMock.calls.filter(call => call.url === "/api/rem/reset").length, 1);
    assert.doesNotMatch(textOf(dom.container), /Corrupted old request|Start fresh with Rem/);
    assert.deepEqual(JSON.parse(storage.getItem("gofer-flow-chat-threads")).map(entry => entry.id), ["mine"]);
    assert.equal(storage.getItem("gofer-flow-chat-thread-meta:rem-worker"), null);
    assert.equal(storage.getItem("gofer-flow-chat-thread-meta:rem-review"), null);
    assert.ok(storage.getItem("gofer-flow-chat-thread-meta:mine"));
    assert.equal(storage.getItem("gofer-flow-rem-reset-pending"), null);
    assert.ok(store.remThreadWasCleared("rem-review"));
    assert.equal(store.getState().resetting, false);
    assert.equal(await store.sendRemMessage("Hello after clearing"), true);
    await dom.flush();
    assert.ok(textOf(dom.byLabel("Conversation with Rem")).includes("Hello after clearing"));
    assert.equal(fetchMock.calls.filter(call => call.url === "/api/rem/messages").length, 1);
  } finally {
    await dom.unmount();
    store.resetRemHomeStore();
  }
});

test("Rem's memory panel lists, corrects and forgets remembered facts", async () => {
  const store = await viteServer.ssrLoadModule("/src/lib/remHomeStore.js");
  store.resetRemHomeStore();
  const created = new Date().toISOString();
  let memories = [
    { id: "a", text: "Uses Google OAuth.", created_at: created },
    { id: "b", text: "Digest at 06:00.", created_at: created },
  ];
  const fetchMock = createFetchMock([
    jsonResponse("/api/workflows", workflowsPayload([])),
    jsonResponse("/api/rem/conversation", { conversation: { id: "c", turn_state: "idle" }, messages: [] }),
    jsonResponse("/api/rem/tasks", { tasks: [] }),
    (url, options) => {
      if (url === "/api/rem/memories" && (options.method || "GET") === "GET") return { ok: true, json: async () => ({ memories }) };
      if (url === "/api/rem/memories/a" && options.method === "PATCH") {
        memories = memories.map(item => item.id === "a" ? { ...item, text: JSON.parse(options.body).text, edited_at: created } : item);
        return { ok: true, json: async () => ({ memories }) };
      }
      if (url === "/api/rem/memories/b" && options.method === "DELETE") {
        memories = memories.filter(item => item.id !== "b");
        return { ok: true, json: async () => ({ memories }) };
      }
      return null;
    },
  ]);
  const dom = await mountReact(React.createElement(appModule.default), fetchMock, { storage: experimentalPluginStorage() });
  const settle = async (done) => {
    for (let attempt = 0; attempt < 30 && !done(); attempt += 1) {
      await new Promise(resolve => setTimeout(resolve, 10));
      await dom.flush();
    }
  };
  try {
    await dom.click(dom.byLabel("Rem"));
    await settle(() => store.getState().status === "ready" && dom.container.querySelector('[aria-label="Rem options"]'));
    await dom.click(dom.byLabel("Rem options"));
    await settle(() => textOf(dom.container).includes("What Rem remembers…"));
    await dom.click(dom.ancestor(dom.byText("What Rem remembers…"), "BUTTON"));
    await settle(() => textOf(dom.container).includes("Uses Google OAuth."));
    const panel = () => dom.ancestor(dom.byExactText("What Rem remembers"), node => node.getAttribute?.("role") === "dialog");
    const button = (scope, label) => allElements(scope).find(node => node.tagName === "BUTTON" && textOf(node) === label);
    const item = text => dom.ancestor(dom.byText(text), "LI");
    assert.match(textOf(panel()), /Uses Google OAuth\..*Digest at 06:00\./s);
    await dom.click(button(item("Uses Google OAuth."), "Edit"));
    const field = dom.byLabel("Memory text");
    await dom.change(field, "");
    assert.equal(dom.byLabel("Memory text").value, "");
    await dom.change(field, "Never use Google OAuth.");
    await dom.click(button(panel(), "Save"));
    await settle(() => textOf(dom.container).includes("Never use Google OAuth."));
    assert.match(textOf(item("Never use Google OAuth.")), /edited/);
    await dom.click(button(item("Digest at 06:00."), "Forget"));
    await settle(() => !textOf(dom.container).includes("Digest at 06:00."));
    assert.doesNotMatch(textOf(panel()), /Digest at 06:00/);
    const patch = fetchMock.calls.find(call => call.url === "/api/rem/memories/a");
    assert.deepEqual(JSON.parse(patch.options.body), { text: "Never use Google OAuth." });
    await dom.click(button(panel(), "Done"));
    assert.doesNotMatch(dom.text(), /Correct anything that’s wrong/);
  } finally {
    await dom.unmount();
    store.resetRemHomeStore();
  }
});

test("Rem's memory panel tags, filters and moves project memories", async () => {
  const store = await viteServer.ssrLoadModule("/src/lib/remHomeStore.js");
  store.resetRemHomeStore();
  const created = new Date().toISOString();
  const projects = [{ root: "/work/site", name: "Site" }, { root: "/work/app", name: "App" }];
  let memories = [
    { id: "g", text: "Prefers short replies.", created_at: created },
    { id: "s", text: "Site deploys from main.", created_at: created, project: "/work/site", project_name: "Site" },
  ];
  const named = root => projects.find(project => project.root === root)?.name;
  const fetchMock = createFetchMock([
    jsonResponse("/api/workflows", workflowsPayload([])),
    jsonResponse("/api/rem/conversation", { conversation: { id: "c", turn_state: "idle" }, messages: [] }),
    jsonResponse("/api/rem/tasks", { tasks: [] }),
    (url, options) => {
      const method = options.method || "GET";
      if (url === "/api/rem/memories" && method === "GET") return { ok: true, json: async () => ({ memories, mode: "on", projects }) };
      if (url === "/api/rem/memories" && method === "POST") {
        const body = JSON.parse(options.body);
        memories = [{ id: "n", text: body.text, created_at: created, added_by: "user", ...(body.project ? { project: body.project, project_name: named(body.project) } : {}) }, ...memories];
        return { ok: true, json: async () => ({ memories, mode: "on", projects }) };
      }
      if (url === "/api/rem/memories/g" && method === "PATCH") {
        const { project } = JSON.parse(options.body);
        memories = memories.map(item => item.id === "g" ? { ...item, project, project_name: named(project) } : item);
        return { ok: true, json: async () => ({ memories, mode: "on", projects }) };
      }
      return null;
    },
  ]);
  const dom = await mountReact(React.createElement(appModule.default), fetchMock, { storage: experimentalPluginStorage() });
  const settle = async (done) => {
    for (let attempt = 0; attempt < 30 && !done(); attempt += 1) {
      await new Promise(resolve => setTimeout(resolve, 10));
      await dom.flush();
    }
  };
  try {
    await dom.click(dom.byLabel("Rem"));
    await settle(() => store.getState().status === "ready" && dom.container.querySelector('[aria-label="Rem options"]'));
    await dom.click(dom.byLabel("Rem options"));
    await settle(() => textOf(dom.container).includes("What Rem remembers…"));
    await dom.click(dom.ancestor(dom.byText("What Rem remembers…"), "BUTTON"));
    await settle(() => textOf(dom.container).includes("Site deploys from main."));
    const panel = () => dom.ancestor(dom.byExactText("What Rem remembers"), node => node.getAttribute?.("role") === "dialog");
    const button = (scope, label) => allElements(scope).find(node => node.tagName === "BUTTON" && textOf(node) === label);
    const item = text => dom.ancestor(dom.byText(text), "LI");
    const tags = () => allElements(panel()).filter(node => String(node.getAttribute?.("class") || node.className || "").includes("rem-memory-tag")).map(textOf);
    // Only the project memory carries a tag.
    assert.deepEqual(tags(), ["Site"]);
    await dom.change(dom.byLabel("Show"), "/work/site");
    await settle(() => !textOf(panel()).includes("Prefers short replies."));
    assert.match(textOf(panel()), /Site deploys from main\./);
    await dom.change(dom.byLabel("Show"), "");
    await settle(() => !textOf(panel()).includes("Site deploys from main."));
    assert.match(textOf(panel()), /Prefers short replies\./);
    await dom.change(dom.byLabel("Show"), "*");
    await settle(() => textOf(panel()).includes("Site deploys from main."));

    // Moving a memory to a project sends only the project, not unchanged text.
    await dom.click(button(item("Prefers short replies."), "Edit"));
    await dom.change(dom.byLabel("Applies to"), "/work/app");
    await dom.click(button(panel(), "Save"));
    await settle(() => tags().includes("App"));
    const patch = fetchMock.calls.find(call => call.url === "/api/rem/memories/g");
    assert.deepEqual(JSON.parse(patch.options.body), { project: "/work/app" });

    await dom.change(dom.byLabel("Something for Rem to remember"), "Site builds with Vite.");
    await dom.change(dom.byLabel("For"), "/work/site");
    await dom.click(button(panel(), "Add"));
    await settle(() => textOf(panel()).includes("Site builds with Vite."));
    const added = fetchMock.calls.find(call => call.url === "/api/rem/memories" && call.options.method === "POST");
    assert.deepEqual(JSON.parse(added.options.body), { text: "Site builds with Vite.", project: "/work/site" });
    assert.match(textOf(item("Site builds with Vite.")), /Site/);
  } finally {
    await dom.unmount();
    store.resetRemHomeStore();
  }
});

test("Rem's memory controls pause saving, add a memory and undo what a reply saved", async () => {
  const store = await viteServer.ssrLoadModule("/src/lib/remHomeStore.js");
  store.resetRemHomeStore();
  const created = new Date().toISOString();
  let mode = "on";
  let memories = [{ id: "tea", text: "Prefers tea", created_at: created }];
  let note = { saved: [{ id: "tea", text: "Prefers tea" }], refused: 1 };
  const conversation = () => ({
    conversation: { id: "c", turn_state: "idle" },
    messages: [
      { id: "m1", role: "user", body: "I like tea", created_at: created },
      { id: "reply-m1", role: "rem", body: "Noted.", created_at: created, memory: note },
    ],
  });
  const fetchMock = createFetchMock([
    jsonResponse("/api/workflows", workflowsPayload([])),
    (url) => url === "/api/rem/conversation" ? { ok: true, json: async () => conversation() } : null,
    jsonResponse("/api/rem/tasks", { tasks: [] }),
    (url, options) => {
      const method = options.method || "GET";
      if (url === "/api/rem/memories" && method === "GET") return { ok: true, json: async () => ({ memories, mode }) };
      if (url === "/api/rem/memories" && method === "POST") {
        memories = [{ id: "east", text: JSON.parse(options.body).text, created_at: created, added_by: "user" }, ...memories];
        return { ok: true, json: async () => ({ memories, mode }) };
      }
      if (url === "/api/rem/memory-mode" && method === "PUT") {
        mode = JSON.parse(options.body).mode;
        return { ok: true, json: async () => ({ memories, mode }) };
      }
      if (url === "/api/rem/messages/reply-m1/undo-memory" && method === "POST") {
        memories = memories.filter(item => item.id !== "tea");
        note = { ...note, undone_at: created };
        return { ok: true, json: async () => ({ memories, mode }) };
      }
      return null;
    },
  ]);
  const dom = await mountReact(React.createElement(appModule.default), fetchMock, { storage: experimentalPluginStorage() });
  const settle = async (done) => {
    for (let attempt = 0; attempt < 30 && !done(); attempt += 1) {
      await new Promise(resolve => setTimeout(resolve, 10));
      await dom.flush();
    }
  };
  const button = (scope, label) => allElements(scope).find(node => node.tagName === "BUTTON" && textOf(node) === label);
  try {
    await dom.click(dom.byLabel("Rem"));
    await settle(() => textOf(dom.container).includes("Saved to memory"));
    const reply = () => dom.ancestor(dom.byText("Saved to memory: “Prefers tea”"), node => String(node.getAttribute?.("class") || node.className || "").includes("rem-memory-note"));
    assert.match(textOf(reply()), /Didn’t save 1 item that looked like a password, key or token/);
    await dom.click(button(reply(), "Undo"));
    await settle(() => textOf(reply()).includes("Undone"));
    assert.ok(fetchMock.calls.some(call => call.url === "/api/rem/messages/reply-m1/undo-memory" && call.options.method === "POST"));
    assert.equal(button(reply(), "Undo"), undefined);

    await dom.click(dom.byLabel("Rem options"));
    await settle(() => textOf(dom.container).includes("What Rem remembers…"));
    await dom.click(dom.ancestor(dom.byText("What Rem remembers…"), "BUTTON"));
    await settle(() => textOf(dom.container).includes("Rem hasn’t saved anything yet."));
    const panel = () => dom.ancestor(dom.byExactText("What Rem remembers"), node => node.getAttribute?.("role") === "dialog");
    const paused = allElements(panel()).find(node => node.tagName === "INPUT" && node.value === "paused");
    await dom.change(paused, "paused");
    await settle(() => textOf(panel()).includes("saves nothing new"));
    assert.deepEqual(JSON.parse(fetchMock.calls.find(call => call.url === "/api/rem/memory-mode").options.body), { mode: "paused" });
    await dom.change(dom.byLabel("Something for Rem to remember"), "Works in Eastern time");
    await dom.click(button(panel(), "Add"));
    await settle(() => textOf(panel()).includes("added by you"));
    assert.match(textOf(panel()), /Works in Eastern time/);
    assert.equal(dom.byLabel("Something for Rem to remember").value, "");
  } finally {
    await dom.unmount();
    store.resetRemHomeStore();
  }
});

test("Rem's memory end dates show in the save note, dim ended memories and offer Keep", async () => {
  const store = await viteServer.ssrLoadModule("/src/lib/remHomeStore.js");
  store.resetRemHomeStore();
  const created = new Date().toISOString();
  // Noon UTC keeps the same day in every timezone the tests run in.
  const future = `${new Date().getFullYear() + 1}-06-30T12:00:00+00:00`;
  const past = "2020-03-01T12:00:00+00:00";
  let memories = [
    { id: "trip", text: "Flying to Oslo.", created_at: created, until: future, ended: false },
    { id: "call", text: "On call this week.", created_at: created, until: past, ended: true },
    { id: "tea", text: "Prefers tea.", created_at: created },
  ];
  const conversation = () => ({
    conversation: { id: "c", turn_state: "idle" },
    messages: [
      { id: "m1", role: "user", body: "Off to Oslo", created_at: created },
      { id: "reply-m1", role: "rem", body: "Noted.", created_at: created, memory: { saved: [{ id: "trip", text: "Flying to Oslo.", until: future }] } },
    ],
  });
  const fetchMock = createFetchMock([
    jsonResponse("/api/workflows", workflowsPayload([])),
    (url) => url === "/api/rem/conversation" ? { ok: true, json: async () => conversation() } : null,
    jsonResponse("/api/rem/tasks", { tasks: [] }),
    (url, options) => {
      const method = options.method || "GET";
      if (url === "/api/rem/memories" && method === "GET") return { ok: true, json: async () => ({ memories, mode: "on" }) };
      const id = url.startsWith("/api/rem/memories/") && method === "PATCH" ? url.split("/").pop() : null;
      if (id) {
        const { until } = JSON.parse(options.body);
        memories = memories.map(item => {
          if (item.id !== id) return item;
          const rest = { ...item };
          delete rest.until;
          delete rest.ended;
          return until ? { ...rest, until: `${until}T23:59:59+00:00`, ended: false } : rest;
        });
        return { ok: true, json: async () => ({ memories, mode: "on" }) };
      }
      return null;
    },
  ]);
  const dom = await mountReact(React.createElement(appModule.default), fetchMock, { storage: experimentalPluginStorage() });
  const settle = async (done) => {
    for (let attempt = 0; attempt < 30 && !done(); attempt += 1) {
      await new Promise(resolve => setTimeout(resolve, 10));
      await dom.flush();
    }
  };
  const button = (scope, label) => allElements(scope).find(node => node.tagName === "BUTTON" && textOf(node) === label);
  const buttons = scope => allElements(scope).filter(node => node.tagName === "BUTTON").map(textOf);
  try {
    await dom.click(dom.byLabel("Rem"));
    await settle(() => textOf(dom.container).includes("Saved to memory"));
    // The note says when Rem stops using the fact, next to its Undo.
    const note = dom.ancestor(dom.byText("Saved to memory until Jun 30"), node => String(node.getAttribute?.("class") || node.className || "").includes("rem-memory-note"));
    assert.match(textOf(note), /Saved to memory until Jun 30, \d{4}: “Flying to Oslo\.”/);
    assert.ok(button(note, "Undo"));

    await dom.click(dom.byLabel("Rem options"));
    await settle(() => textOf(dom.container).includes("What Rem remembers…"));
    await dom.click(dom.ancestor(dom.byText("What Rem remembers…"), "BUTTON"));
    await settle(() => textOf(dom.container).includes("On call this week."));
    const item = text => dom.ancestor(dom.byExactText(text), "LI");
    // An ended memory is dimmed with Keep and Forget; the others can get an end date.
    assert.equal(item("On call this week.").getAttribute("data-ended"), "true");
    assert.match(textOf(item("On call this week.")), /Ended Mar 1, 2020/);
    assert.deepEqual(buttons(item("On call this week.")), ["Keep", "Forget"]);
    assert.equal(item("Flying to Oslo.").getAttribute("data-ended"), null);
    assert.match(textOf(item("Flying to Oslo.")), /Until Jun 30, \d{4}/);
    assert.deepEqual(buttons(item("Prefers tea.")), ["Edit", "Set an end date", "Forget"]);

    await dom.click(button(item("On call this week."), "Keep"));
    await settle(() => item("On call this week.").getAttribute("data-ended") === null);
    const kept = fetchMock.calls.find(call => call.url === "/api/rem/memories/call");
    assert.deepEqual(JSON.parse(kept.options.body), { until: null });
    assert.doesNotMatch(textOf(item("On call this week.")), /Ended/);

    await dom.click(button(item("Prefers tea."), "Set an end date"));
    await settle(() => dom.container.querySelector('[aria-label="End date"]'));
    const year = new Date().getFullYear() + 2;
    await dom.change(dom.byLabel("End date"), `${year}-01-15`);
    await dom.click(button(item("Prefers tea."), "Save"));
    await settle(() => textOf(item("Prefers tea.")).includes("Until"));
    const dated = fetchMock.calls.find(call => call.url === "/api/rem/memories/tea");
    assert.deepEqual(JSON.parse(dated.options.body), { until: `${year}-01-15` });
    assert.match(textOf(item("Prefers tea.")), new RegExp(`Until Jan 15, ${year}`));
  } finally {
    await dom.unmount();
    store.resetRemHomeStore();
  }
});

test("Rem home's welcome says Rem's app isn't installed and opens its setting", async () => {
  const store = await viteServer.ssrLoadModule("/src/lib/remHomeStore.js");
  const workspace = await viteServer.ssrLoadModule("/src/components/RemHomeWorkspace.jsx");
  const mount = async (remProvider, capabilities) => {
    store.resetRemHomeStore();
    const fetchMock = createFetchMock([
      jsonResponse("/api/rem/conversation", { conversation: { id: "rem", turn_state: "idle" }, messages: [] }),
      jsonResponse("/api/rem/tasks", { tasks: [] }),
      jsonResponse("/api/provider/capabilities?snapshot=1", capabilities),
    ]);
    const opened = [];
    const dom = await mountReact(React.createElement(workspace.default, { remProvider, onOpenSettings: target => opened.push(target) }), fetchMock);
    await store.refreshRemHome();
    for (let n = 0; n < 40 && !dom.container.querySelector?.(".rem-provider-problem"); n++) { await new Promise(resolve => setTimeout(resolve, 5)); await dom.flush(); }
    return { dom, opened };
  };
  let { dom, opened } = await mount({ provider: "codex", chatProvider: "" }, remProviderCapabilities());
  try {
    assert.match(dom.text(), /Rem's app, Codex, isn't installed on this computer\. Choose another in Settings › Rem\./);
    assert.doesNotMatch(dom.text(), /What's running right now\?/, "the warning replaces the ideas");
    await dom.click(dom.ancestor(dom.byText("Open Settings › Rem"), "BUTTON"));
    assert.deepEqual(opened, [{ selectors: ['[data-setting-row="provider"] select'] }]);
  } finally { await dom.unmount(); store.resetRemHomeStore(); }

  // Rem's chat provider wins over the default one, and sign-in gets its own wording.
  const signIn = remProviderCapabilities();
  signIn.providers[0] = { ...signIn.providers[0], discoveryStatus: "unauthenticated" };
  ({ dom, opened } = await mount({ provider: "codex", chatProvider: "claude_code" }, signIn));
  try {
    assert.match(dom.text(), /Rem's app, Claude Code, needs you to sign in\./);
    await dom.click(dom.ancestor(dom.byText("Open Settings › Rem"), "BUTTON"));
    assert.deepEqual(opened, [{ selectors: ['[data-setting-row="chatProvider"] select'] }]);
  } finally { await dom.unmount(); store.resetRemHomeStore(); }

  // A usable app keeps the ideas.
  ({ dom } = await mount({ provider: "claude_code", chatProvider: "" }, remProviderCapabilities()));
  try {
    assert.match(dom.text(), /What's running right now\?/);
    assert.doesNotMatch(dom.text(), /isn't installed/);
  } finally { await dom.unmount(); store.resetRemHomeStore(); }
});

test("Rem folder links open projects, and its menu opens provider settings", async () => {
  const store = await viteServer.ssrLoadModule("/src/lib/remHomeStore.js");
  store.resetRemHomeStore();
  const opened = [];
  const workspace = {
    grantUserPath: async path => { opened.push(path); return { path }; },
    // "/shortcut" is a symlink to the linked folder: path info gives the real path.
    getPathInfo: async target => {
      const path = target === "/shortcut" ? "/linked-project" : target;
      return { path, exists: true, isDirectory: path === "/linked-project", isFile: path !== "/linked-project" };
    },
    trustProjectRoot: async path => path,
    listDirectory: async ({ currentPath }) => ({ directory: currentPath, entries: [] }),
    gitStatus: async () => ({ active: false }),
    gitWorktrees: async () => ({ worktrees: [] }),
  };
  const fetchMock = createFetchMock([
    jsonResponse("/api/workflows", workflowsPayload([])),
    jsonResponse("/api/rem/conversation", { conversation: { id: "rem", turn_state: "idle" }, messages: [{ id: "result", role: "rem", created_at: new Date().toISOString(), body: "[Tool folder](/linked-project) and [Shortcut folder](/shortcut)" }] }),
    jsonResponse("/api/rem/tasks", { tasks: [] }),
    jsonResponse("/api/projects/open", { projectRoot: "/linked-project", workflows: [] }),
  ]);
  const dom = await mountReact(React.createElement(appModule.default), fetchMock, { desktop: { workspace, textFiles: { read: async () => ({ content: "# Audit report" }) } }, storage: experimentalPluginStorage() });
  try {
    await dom.click(dom.byLabel("Rem"));
    for (let n = 0; n < 20 && !textOf(dom.container).includes("Tool folder"); n++) { await new Promise(resolve => setTimeout(resolve, 10)); await dom.flush(); }
    await dom.click(dom.byLabel("Rem options"));
    await dom.click(dom.ancestor(dom.byText("Provider, model and effort…"), "BUTTON"));
    await dom.flush();
    assert.ok(textOf(dom.container).includes("Default provider"));
    await dom.click(dom.byLabel("Close settings"));
    // A folder outside the open project opens only after the user agrees.
    await dom.click(dom.ancestor(dom.byText("Tool folder"), "A"));
    await dom.flush();
    const asked = await answerConfirm(dom, false);
    assert.match(asked.message, /Open "\/linked-project" as a project\?/);
    assert.equal(asked.confirmLabel, "Open project");
    assert.equal(fetchMock.calls.some(call => call.url === "/api/projects/open"), false);
    assert.deepEqual(opened, [], "Cancel leaves the window no grant for the folder");
    // A link through a symlink asks about the folder it really leads to.
    await dom.click(dom.ancestor(dom.byText("Shortcut folder"), "A"));
    await dom.flush();
    const askedShortcut = await answerConfirm(dom, false);
    assert.match(askedShortcut.message, /Open "\/linked-project" as a project\?/);
    assert.deepEqual(opened, []);
    await dom.click(dom.ancestor(dom.byText("Tool folder"), "A"));
    await dom.flush();
    await answerConfirm(dom, true);
    assert.deepEqual(opened, ["/linked-project"]);
    assert.ok(fetchMock.calls.some(call => call.url === "/api/projects/open" && JSON.parse(call.options.body).projectRoot === "/linked-project"));
    assert.equal(dom.byLabel("File explorer").getAttribute("aria-selected"), "true");
  } finally { await dom.unmount(); store.resetRemHomeStore(); }
});

